/* pastas: salvar guarda o conteúdo numa pasta, que fica no Perfil */
/* [chave, nome, conteúdos de exemplo (ids), secreta] — pasta secreta só você vê, mesmo com o perfil público */
const FOLDERS = [["salvos","Salvos",[],false],["ideias","Ideias para o bairro",[5,1,9,13,21,22,3,15,23,6,19,17],false],["leituras","Leituras da assembleia",[8,18,4,15,24],true]];
(store.get("pastas", []) || []).forEach(f=>{ if (Array.isArray(f) && !FOLDERS.some(x=>x[0]===f[0])) FOLDERS.push([f[0], f[1], [], !!f[3]]); });   /* pastas criadas por você */
const folderName = k => (FOLDERS.find(f=>f[0]===k)||FOLDERS[0])[1];
const folderItems = k => { const f = FOLDERS.find(x=>x[0]===k);
  const mine = [...S.saved].filter(u=>(S.savedIn[u]||"salvos")===k).map(u=>findItem(u)).filter(Boolean);
  return mine.concat(f[2].map(id=>POOL.find(p=>p.id===id)).filter(Boolean).map(p=>withUid(p,"f"+k))); };
const folderCount = k => folderItems(k).length;
const folderArt = k => { const ids = folderItems(k).slice(0,3).map(i=>i.id);
  if (!ids.length) return `<span class="bempty">${ic("bookmark")}</span>`;          /* pasta vazia: um bloco só, com o ícone */
  return [0,1,2].map(i=>miniArt(ids[i % ids.length])).join(""); };
const likesOf = it => ((it.conta || typeof it.id!=="number") ? 0 : 14 + (it.id*37)%180) + (S.liked.has(it.uid)?1:0);   /* conta real: só as curtidas de verdade (ainda locais) */
const ic = (n, cls="") => `<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${ICON[n]}</svg>`;
const esc = s => String(s).replace(/[&<>"]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
/* TEXTO DE TERCEIROS (12 nov 2026): o que vem do servidor e foi escrito por pessoas (nomes, cidades, títulos, locais, anúncios)
   entra limpo: sem < e >, e com aspas tipográficas. Assim, mesmo onde a tela não usa esc(), ninguém injeta código. */
const limpo = s => s == null ? s : String(s).replace(/[<>]/g, "").replace(/"/g, "”");
const limpoObj = o => { const r = {}; for (const [k, v] of Object.entries(o || {})) r[k] = typeof v === "string" && !/_url$/.test(k) ? limpo(v) : v; return r; };
const linkSeguro = u => /^https?:\/\//i.test(String(u || "")) ? String(u) : "";
/* curtir e salvar: só ícones; o preenchido indica que está ativo */
const icFill = (n, on) => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true" ${on?'style="fill:currentColor"':""}>${ICON[n]}</svg>`;
const likeBtn = it => { const on = S.liked.has(it.uid);
  return `<button class="actbtn${on?" on":""}" type="button" data-act="like" data-uid="${it.uid}" aria-pressed="${on}" aria-label="${on?"Descurtir":"Curtir"}, ${likesOf(it)} curtidas">${icFill("heart",on)}<span class="cnt">${likesOf(it)}</span></button>`; };
/* AÇÕES NO CARD (revisão 14 nov 2026, referência Pinterest): com mouse, ao passar por cima aparecem a pasta (em cima à esquerda),
   Salvar (em cima à direita, um clique guarda na última pasta usada) e Compartilhar (embaixo à direita). No toque, as ações
   ficam na barra do cartão aberto, como antes. */
const ultimaPasta = () => { const k = store.get("ultimaPasta", ""); return FOLDERS.some(f=>f[0]===k) ? k : FOLDERS[0][0]; };
const tileAcoes = it => { const on = S.saved.has(it.uid), k = on ? (S.savedIn[it.uid] || ultimaPasta()) : ultimaPasta();
  return `<span class="tacts${on ? " salvo" : ""}"><button class="tpasta" type="button" data-act="savepick" data-uid="${it.uid}" aria-label="Escolher a pasta (agora: ${esc(folderName(k))})">${esc(folderName(k))}${ic("chev","sm")}</button>
    <button class="tsalvar" type="button" data-act="savequick" data-uid="${it.uid}" aria-pressed="${on}" aria-label="${on ? "Salvo em " + esc(folderName(k)) + ". Tocar para remover" : "Salvar em " + esc(folderName(k))}">${on ? "Salvo" : "Salvar"}</button>
    <button class="tshare" type="button" data-act="share" data-uid="${it.uid}" aria-label="Compartilhar" title="Compartilhar">${ic("share","sm")}</button></span>`; };
const saveBtn = (uid, cls="iconbtn") => { const on = S.saved.has(uid);
  return `<button class="${cls}" type="button" data-act="save" data-uid="${uid}" aria-pressed="${on}" aria-label="${on?"Salvo em "+folderName(S.savedIn[uid])+". Tocar para remover":"Salvar em uma pasta"}">${icFill("bookmark",on)}</button>`; };
function tempo(min){ if(min<60) return `há ${min} min`; if(min<1440) return `há ${Math.round(min/60)} h`; const d = Math.round(min/1440); if (d===1) return "ontem"; if (d<=7) return `há ${d} dias`;
  const t = new Date(new Date(2026,10,8,12) - min*60000); return `${t.getDate()} ${["jan","fev","mar","abr","mai","jun","jul","ago","set","out","nov","dez"][t.getMonth()]}${t.getFullYear()!==2026?" "+t.getFullYear():""}`; }
const debounce = (fn, ms) => { let t; return (...a) => { clearTimeout(t); t = setTimeout(()=>fn(...a), ms); }; };

