const temaSem = (s) => (s || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9 \-]+/g, " ").replace(/\s+/g, " ");
const temaConta = (re, t) => { re.lastIndex = 0; const m = t.match(re); return m ? new Set(m).size : 0; };
function temaDe(titulo, chamada) {
  const a = " " + temaSem(titulo) + " ", b = " " + temaSem(chamada) + " ";
  let melhor = TEMA_OUTROS, max = 0;
  for (const [k, re] of TEMAS_TERMOS) {
    const p = 2 * temaConta(re, a) + temaConta(re, b);
    if (p > max) { max = p; melhor = k; }
  }
  return melhor;
}
