/* FILTROS RÁPIDOS (9 nov 2026): na linha do algoritmo, um toque recorta o feed da aba atual; um por vez.
   Em alta: últimas 72 horas, com mais repercussão (a mesma notícia em mais fontes da base, ou mais participação).
   Perto de você: da sua cidade ou do seu estado. Desmentidos: checagens das agências da base que desmentem algo. */
const RAPIDOS = [["alta","Em alta","raio"],["perto","Por perto","pin"],["desmentidos","Desmentidos","desm"]];
const ehChecagem = it => (ORG[it.org] || {}).natureza==="Checagem de fatos";
/* TheJournal.ie FactCheck entrega o feed geral do jornal, não só as checagens: fica fora até o feed ser corrigido */
const CHECA_MISTO = /thejournal\.ie/;
const DESM = /\b(falso|falsa|falsos|falsas|boato|boatos|engan\w+|fake|mentira\w*|desinforma\w*|n[aã]o [eé] verdade|tir\w+ de contexto|montagem|manipulad\w+|n[aã]o procede|false|falsely|misleading|hoax|bulo\w*|engañ\w+|falsedad\w*|desinformaci\w+|out of context|fuera de contexto|fabricated|doctored|erroneamente|err[oó]neamente|wrongly|inventa\w*|invent\w+)\b/i;
const DESM_NEG = /^(n[aã]o|no|nem)\b|\bn[aã]o (disse|h[aá]|existe|[eé]|transfere|mostra)\b|, n[aã]o (de|em|do|da|no|na)\b/i;
const desmente = it => ehChecagem(it) && !CHECA_MISTO.test((ORG[it.org] || {}).site || "") && (DESM.test(it.titulo + " " + (it.texto || "")) || DESM_NEG.test(it.titulo));
const VEREDITOS = [[/\b(engan\w+|misleading|engañ\w+)\b/i,"Enganoso"],[/\b(tir\w+ de contexto|out of context|fuera de contexto)\b/i,"Fora de contexto"],[/\b(montagem|manipulad\w+|doctored|fabricated)\b/i,"Montagem"],[/\b[eé] de (19|20)\d\d|\bn[aã]o [eé] posterior|\bé de (janeiro|fevereiro|março|abril|maio|junho|julho|agosto|setembro|outubro|novembro|dezembro)\b/i,"Conteúdo antigo"],[/\b(falso|falsa|falsos|falsas|false|falsely|fake|bulo\w*|hoax|n[aã]o disse|inventa\w*)\b/i,"Falso"]];
const veredito = it => { const t = it.titulo + " " + (it.texto || ""), v = VEREDITOS.find(([r])=>r.test(t)); return v ? v[1] : ""; };
const calor = it => (it.ext && it.ext.verif ? it.ext.verif.length * 12 : 0) + participacao(it) / 40;
function rapidoAplica(l){
  if (S.rapido==="desmentidos") return l.filter(desmente).sort((a,b)=>a.min-b.min);
  if (S.rapido==="perto"){ const R = minhaRegiao(); if (!R.cidade && !R.uf) return [];
    return l.map(it=>[it, prox(it)]).filter(x=>x[1]>=2).sort((a,b)=>b[1]-a[1] || a[0].min-b[0].min).map(x=>x[0]); }
  if (S.rapido==="alta") return l.filter(it=>!it.daArte && it.min <= 4320 && calor(it) > 0).sort((a,b)=>calor(b)-calor(a) || a.min-b.min);
  return l; }
const rapidosHTML = () => `<div class="qf" role="group" aria-label="Filtros rápidos">${RAPIDOS.map(([k,n,i])=>`<button class="qchip" type="button" data-act="rapido" data-k="${k}" aria-pressed="${S.rapido===k}">${ic(i,"sm")}${n}</button>`).join("")}</div>`;
const kindOf = it => it.autoral ? "Autoral · " + AUTORAL[it.autoral][0] : it.base ? it.doc : desmente(it) ? "Desmentido" + (veredito(it) ? " · " + veredito(it) : "") : ehChecagem(it) && it.ext ? "Checagem" : it.arte ? "Arte · " + (CAT_ARTE[it.catArte] || "Imagem") : it.daRede ? (TIPO_REDE[it.rtipo] || "Publicação") + " · " + REDES[it.rede].nome : it.ext && it.tipo==="texto" && ORG[it.org] && ORG[it.org].fonte ? (it.lingua && it.lingua!=="pt" ? "Notícia · " + it.lingua.toUpperCase() : "Notícia") : it.tipo==="votacao" ? (it.fase==="apoios" ? "Proposta de votação" : it.critico ? "Eleição" : "Votação") : KIND[it.tipo];
const KIND = {video:"Vídeo", imagem:"Publicação", texto:"Publicação", evento:"Evento", enquete:"Consulta", votacao:"Votação", chamado:"Chamado", documento:"Documento"};
/* cada aba tem o leiaute que melhor serve ao seu tipo (4º campo):
   blocos (Início misto) · video (1 coluna) · agenda (eventos e chamados, pelo que acontece ou vence primeiro) · cedula (voto no cartão) · arquivo (lista de documentos) */
const FTABS = [["tudo","Tudo",null,"blocos"],["publicacoes","Publicações",["imagem","texto","video"],"blocos"],["videos","Canais",["video"],"video"],["documentos","Documentos",["documento"],"arquivo"],["arte","Arte","arte","blocos"]];

/* =====================================================================
   3. Estado (preferências ficam salvas no navegador)
   ===================================================================== */
const S = {
  tema: store.get("tema","auto"), vista: store.get("vista","blocos"), algo: store.get("algo", true), tab: store.get("tab","tudo"), origens: store.get("origens", ["pt"]), perto: store.get("perto", true), regiao: store.get("regiao", ""),
  temas: temaListaNova(store.get("temas", ["Moradia","Mobilidade","Alimentação e campo","Educação"])), mix: store.get("mix", 60),
  pausas: store.get("pausas", true), orgsVisiveis: store.get("orgsVisiveis", false), publico: store.get("publico", false), assinou: store.get("assinou", false), interesses: temaListaNova(store.get("interesses", ["Mobilidade","Alimentação e campo","Meio ambiente e clima"])), intDraft:null, profTab:"publicacoes", pubTab:"publicacoes", pubFolder:null, profQ:"", profFolder:null, usarOrgs: store.get("usarOrgs", true),
  follow: new Set(store.get("follow", ["bairro-vivo","hortas-leste","pedala-cwb"])), saved: new Set(store.get("saved", [])), savedIn: store.get("savedIn", {}), liked: new Set(store.get("liked", ["13-0","27-0","16-0"])), shared: new Set(store.get("shared", ["4-0","15-0","6-0"])),
  autoplay: store.get("autoplay", true),
  localAuto: store.get("localAuto", false), localQuando: store.get("localQuando", 0), aprendeLugares: store.get("aprendeLugares", true), lugares: store.get("lugares", {}), lugaresFora: store.get("lugaresFora", []), apTemas: store.get("apTemas", {}), apFontes: store.get("apFontes", {}),
  filt: {temas:[], cidades:[], minhas:false, conf:0}, fdraft:null, ord:"padrao",
  pollVote:store.get("pollVote", {}), rsvp:store.get("rsvp", {}), support:store.get("support", {}), reports:{}, help:store.get("help", {}), inscr:store.get("inscr", {}), formalDone:store.get("formalDone", {}), created:[], vid:{},
  rapido:null, adOculta:new Set(), orgTab:"mural", exploreTema:null, exploreQ:"", pinMode:{}, textOpen:{}
};
if (!FTABS.some(t=>t[0]===S.tab)) S.tab = "tudo";
/* DADOS DA CONTA NO SERVIDOR (11 nov 2026): curtidas, salvos, pastas, votos, apoios, presenças e afins seguem a conta entre aparelhos.
   Quem está fora da conta continua só com o aparelho. Ao entrar, o que já está no servidor vale; o que ainda não está sobe do aparelho. */
const CONTA_SYNC = ["liked","saved","savedIn","pastas","secoes","shared","follow","pollVote","support","formalDone","rsvp","help","inscr","canaisSalvos","aprendido"];
let CD_FILA = new Set(), CD_T = null, CD_DE = null;
/* SEÇÕES DO PERFIL (14/11, referência Pinterest): até 3 seções, até 5 pastas em cada, com salvos e publicações.
   O cadeado da seção vale para as pastas dela; uma pasta pode ficar secreta dentro de uma seção aberta, nunca o contrário.
   Pastas fora das seções: só você vê. Seção nova nasce fechada. */
let MAX_SEC = 3, MAX_PSEC = 5;   /* o painel ajusta (secoes_max, pastas_por_secao) */
S.secoes = store.get("secoes", null);
S.canaisSalvos = new Set((store.get("canaisSalvos", []) || []).filter(k=>/^(tv|rd):[\w-]{1,40}$/.test(k)));   /* 16/11: canais e rádios salvos seguem a conta (decisão da Amanda) */
if (!Array.isArray(S.secoes)) S.secoes = [{id:"s1", nome:"Ideias e leituras", aberta:true, pastas:FOLDERS.filter(f=>f[0]!=="salvos").slice(0, MAX_PSEC).map(f=>f[0])}];
S.orgFiltro = store.get("orgFiltro", "tudo"); S.orgAba = store.get("orgAba", "tudo"); S.orgVista = store.get("orgVista", "soltos");
const secDe = k => S.secoes.find(x=>x.pastas.includes(k));
const pastaAberta = f => { const x = secDe(f[0]); return !!(x && x.aberta && !f[3]); };
const secLimpa = () => S.secoes.forEach(x=>{ x.pastas = x.pastas.filter(k=>FOLDERS.some(f=>f[0]===k)).slice(0, MAX_PSEC); });
/* VITRINE (15/11, Amanda): retrato das pastas das seções abertas, para quem visita o perfil (aba Pastas).
   Vai para conta_dados (chave "vitrine"), que só a dona lê; quem visita usa perfil_pastas, que confere de novo no servidor
   as seções abertas, as pastas secretas e o perfil público. Conteúdo de comunidade criada por pessoas não sai do perfil. */
var VIT_T = null;
function vitItem(it){ if (!it) return null; const o = ORG[it.org] || {}; if (o.comunidade) return null;
  const https = v => typeof v === "string" && /^https:\/\//.test(v) && v.length <= 1000 ? v : undefined;
  return {id:String(it.id), tipo:it.tipo || "texto", titulo:String(it.titulo || "").slice(0, 160), tema:it.tema || undefined, org:o.nome || undefined,
    foto:https(it.foto) || https(it.poster), yt:/^[A-Za-z0-9_-]{6,20}$/.test(it.yt || "") ? it.yt : undefined, url:it.ext ? https(it.ext.url) : undefined}; }
function vitrineMonta(){ secLimpa(); let n = 30, v;
  do { v = {publico:!!S.publico, secoes:S.secoes.filter(x=>x.aberta).map(x=>({id:x.id, nome:x.nome,
      pastas:x.pastas.map(k=>FOLDERS.find(f=>f[0]===k)).filter(f=>f && !f[3] && f[0] !== "salvos").map(f=>({k:f[0], nome:f[1], itens:folderItems(f[0]).map(vitItem).filter(Boolean).slice(0, n)}))}))};
    n = Math.floor(n * .7); } while (JSON.stringify(v).length > 90000 && n > 2);   /* cabe no limite de 64 KB da linha */
  return v; }
function vitrineAgenda(){ if (!SB || !ME.user || CD_DE !== ME.user.id) return; clearTimeout(VIT_T); VIT_T = setTimeout(vitrineEnvia, 2000); }
async function vitrineEnvia(){ if (!SB || !ME.user || CD_DE !== ME.user.id) return;
  try{ await SB.from("conta_dados").upsert({user_id:ME.user.id, chave:"vitrine", valor:vitrineMonta(), atualizada_em:new Date().toISOString()}); }catch(e){} }
const persist = k => { store.set(k, S[k] instanceof Set ? [...S[k]] : S[k]); if (CONTA_SYNC.includes(k)) contaDadosAgenda(k); if (k === "publico") vitrineAgenda(); };
const cdValor = k => k==="pastas" ? (store.get("pastas", []) || []) : k==="aprendido" ? apResumo() : (S[k] instanceof Set ? [...S[k]] : (S[k] || {}));
function contaDadosAgenda(k){ if (!SB || !ME.user || CD_DE!==ME.user.id) return; CD_FILA.add(k); if (["saved","savedIn","secoes","pastas"].includes(k)) vitrineAgenda(); clearTimeout(CD_T); CD_T = setTimeout(contaDadosEnvia, 1200); }
async function contaDadosEnvia(){ if (!SB || !ME.user || CD_DE!==ME.user.id || !CD_FILA.size) return; const ks = [...CD_FILA], uid = ME.user.id; CD_FILA = new Set();
  try{ const {error} = await SB.from("conta_dados").upsert(ks.map(k=>({user_id:uid, chave:k, valor:cdValor(k), atualizada_em:new Date().toISOString()})));
    if (error) ks.forEach(k=>CD_FILA.add(k)); }catch(e){ ks.forEach(k=>CD_FILA.add(k)); } }
async function contaDadosCarrega(){ if (!SB || !ME.user || CD_DE===ME.user.id) return; const uid = ME.user.id; let rows;
  try{ const r = await SB.from("conta_dados").select("chave,valor").eq("user_id", uid); if (r.error) return; rows = r.data || []; }catch(e){ return; }
  if (!ME.user || ME.user.id!==uid) return;
  const sv = Object.fromEntries(rows.map(r=>[r.chave, r.valor])); let mudou = false;
  CONTA_SYNC.forEach(k=>{ const v = sv[k];
    if (v==null){ CD_FILA.add(k); return; }   /* ainda não está no servidor: sobe o que está no aparelho */
    if (k==="pastas"){ const ps = Array.isArray(v) ? v.filter(f=>Array.isArray(f)) : []; store.set("pastas", ps);
      ps.forEach(f=>{ if (!FOLDERS.some(x=>x[0]===f[0])){ FOLDERS.push([f[0], f[1], [], !!f[3]]); mudou = true; } }); return; }
    if (k==="secoes"){ if (Array.isArray(v)){ S.secoes = v.filter(x=>x && Array.isArray(x.pastas)).slice(0, MAX_SEC); store.set("secoes", S.secoes); mudou = true; } return; }
    if (k==="aprendido"){ apAplica(v); return; }
    if (S[k] instanceof Set) S[k] = new Set(Array.isArray(v) ? v : []); else S[k] = (v && typeof v==="object" && !Array.isArray(v)) ? v : {};
    store.set(k, S[k] instanceof Set ? [...S[k]] : S[k]); mudou = true; });
  CD_DE = uid; contaDadosEnvia(); vitrineAgenda(); if (mudou) render(); }
let sessionStart = Date.now();
const HOST_THEME = document.documentElement.getAttribute("data-theme");
function applyTheme(){ const r = document.documentElement;
  if (S.tema==="auto"){ HOST_THEME ? r.setAttribute("data-theme", HOST_THEME) : r.removeAttribute("data-theme"); }
  else r.setAttribute("data-theme", S.tema==="escuro" ? "dark" : "light"); }
applyTheme();

/* =====================================================================
   4. Selo de confiabilidade
   ===================================================================== */
const STOPS = [[0,[192,54,44]],[45,[194,122,14]],[70,[110,154,58]],[85,[46,139,87]],[100,[15,107,62]]];
function tone(sc){ for(let k=1;k<STOPS.length;k++){ const [a,ca]=STOPS[k-1],[b,cb]=STOPS[k]; if(sc<=b){ const t=(sc-a)/(b-a); return "rgb("+ca.map((v,i)=>Math.round(v+(cb[i]-v)*t)).join(",")+")"; } } return "rgb(15,107,62)"; }
/* CRITÉRIOS DA NOTA (13 nov 2026): faixas do selo e nota de publicação com fonte vêm de Regras e parâmetros, no backoffice.
   Faixa vermelha abaixo de 50 (decisão #39). Publicação com fonte da base não herda a nota da fonte: mostra “Cita fonte confiável”, sem número (decisão #40). */
let SELO_ALTA = 90, SELO_CONF = 75, SELO_BAIXA = 50, REP_POUCO = 75, REP_MUITO = 90, SELO_AUTO_REP = 75;
function sealOf(it){
  const sc = it.id in SEAL ? SEAL[it.id] : (String(it.uid).startsWith("c") ? null : 80);
  if (it.autoral) return {sc:null, lv:"na", label:"Conteúdo autoral"};
  if (it.fontePub && it.fontePub.situacao==="avaliacao") return {sc:null, lv:"pend", label:"Fonte não verificada"};
  if (it.fontePub && it.fontePub.situacao==="recusada") return {sc:null, lv:"bad", label:"Fonte não confiável", tone:tone(12)};
  /* decisão #40 (13 nov 2026): quem publica não é a fonte oficial; a publicação não recebe nota, mostra que cita fonte confiável */
  if (it.fontePub && it.fontePub.situacao==="base") return {sc:null, lv:"ok", label:"Cita fonte confiável", tone:tone(SELO_CONF)};
  if (it.conta && !it.fontePub && sc===null && !it.arte && !["votacao","enquete"].includes(it.tipo)) return {sc:null, lv:"pend", label:"Sem fonte"};
  /* publicação original (conta real ou criada no protótipo) ainda não passa pelo motor: não é "sem fatos", é "ainda sem selo" */
  if (sc===null && !it.arte && (it.conta || String(it.uid).startsWith("c")) && !["votacao","enquete"].includes(it.tipo)) return {sc:null, lv:"pend", label:"Ainda sem selo"};
  if (sc===null) return {sc:null, lv:"na", label:"Sem fatos a checar"};
  const lv = sc>=SELO_CONF ? "ok" : sc>=SELO_BAIXA ? "warn" : "bad";
  const label = sc>=SELO_ALTA ? "Alta confiança" : sc>=SELO_CONF ? "Confiável" : sc>=SELO_BAIXA ? "Confiança moderada" : "Baixa confiança";
  return {sc, lv, label, tone: tone(sc)};
}
