  if (it.coletada && /^n[0-9a-f]{32}$/.test(it.id || "")){ const h = it.id.slice(1); nid = `${h.slice(0,8)}-${h.slice(8,12)}-${h.slice(12,16)}-${h.slice(16,20)}-${h.slice(20)}`; }
  else if (it.daArte) tipo = "arte"; else if (it.conta) tipo = "publicacao"; else return;
