async function cfgCarrega(){ if (!SB) return; try{ const r = await SB.rpc("config_publica"); if (r.error || !r.data) return; const antes = CFG.selo_donos; CFG = Object.assign({}, CFG, r.data);
  if (antes !== CFG.selo_donos) render(); }catch(e){} }
function donoDe(it){ if (!CFG.selo_donos) return null; const o = ORG[it.org] || {}; if (!o.fonte) return null; const d = DONOS_FONTE.find(x=>x.nome.test(o.nome || "")); if (!d) return null;
  const tx = semAcento((it.titulo || "") + " " + (it.texto || it.chamada || "")), m = d.vigia ? tx.match(d.vigia) : null;
  return {d, cita:m ? m[0] : null}; }
function seloMarcas(it){ const o = ORG[it.org] || {}, nat = String(o.natureza || ""), m = [];
  const dias = it.ext ? (it.ext.data && !isNaN(Date.parse(it.ext.data)) ? (Date.now() - Date.parse(it.ext.data))/864e5 : (it.min || 0)/1440) : 0;   /* idade pela data de publicação; sem data, pelo tempo guardado */
  if (dias > SELO_ANTIGO_DIAS) m.push({k:"antigo", ic:"clock", t:"Conteúdo antigo", d:it.ext.data ? "de " + dLabel(it.ext.data) : "", x:"Publicado há mais de 3 meses e voltou a circular. Confira se ainda vale antes de compartilhar."});
  if (o.fonte && OFICIAL_RE.test(nat)) m.push({k:"oficial", ic:"doc", t:"Dado oficial", d:"", x:"Fonte primária: " + nat.replace(/^canal no YouTube · /, "").toLowerCase() + "."});
  if (o.fonte && CHECA_RE.test(nat)) m.push({k:"checado", ic:"check", t:"Agência de checagem", d:o.nome, x:esc(o.nome) + " é uma agência de checagem de fatos."});
  else if (it.ext && it.ext.verif && it.ext.verif.length){ const ag = new Set(Object.values(ORG).filter(x=>x && x.fonte && CHECA_RE.test(String(x.natureza || ""))).map(x=>x.nome));
    const v = it.ext.verif.filter(x=>ag.has(x.fonte)); if (v.length) m.push({k:"checado", ic:"check", t:"Checado por agência", d:"", x:"Checagem sobre o mesmo assunto: " + v.slice(0, 2).map(x=>`<a href="${esc(x.url)}" target="_blank" rel="noopener">${esc(x.fonte)} ↗</a>`).join(", ") + "."}); }
  if (reforco(it)) m.push({k:"reforco", ic:"globe", t:"Reforço internacional", d:it.paises.map(bandeira).join(""), x:"Fontes de mais de um país publicaram a mesma notícia."});
  if (it.lingua && it.lingua!=="pt") m.push({k:"lingua", ic:"globe", t:"Em " + (LINGUA_NOME[it.lingua] || it.lingua), d:"", x:"A matéria original não está em português."});
  if (o.linha) m.push({k:"linha", ic:"info", t:/ativista/i.test(o.linha) ? "Mídia ativista" : "Linha editorial declarada", d:"", x:esc(o.linha)});
  if (it.daRede) m.push({k:"individual", ic:"people", t:"Fonte individual", d:REDES[it.rede].nome, x:"Perfil pessoal trazido de outra rede, não uma redação."});
  if (it.seloAjuste) m.push({k:"ajuste", ic:"people", t:"Nota ajustada pela comunidade", d:"", x:"Contribuições com fonte mudaram a nota."});
  const dn = donoDe(it);
  if (dn && dn.cita) m.push({k:"proprio", ic:"info", t:"Fala do próprio grupo", d:dn.d.grupo, x:`A notícia cita “${esc(dn.cita.toUpperCase()===dn.cita ? dn.cita : dn.cita.replace(/\b\w/g, c=>c.toUpperCase()))}”, do mesmo grupo da fonte. Leia sabendo do interesse. <b>Você sabia</b> que ${esc(dn.d.soube)}`});
  else if (dn) m.push({k:"dono", ic:"people", t:"Você sabia?", d:dn.d.grupo, x:"<b>Você sabia</b> que " + esc(dn.d.soube)});
  const ordem = ["checado","proprio"]; return m.filter(x=>ordem.includes(x.k)).sort((a,b)=>ordem.indexOf(a.k)-ordem.indexOf(b.k)).concat(m.filter(x=>!ordem.includes(x.k))); }   /* checagem de agência vem primeiro: é a marca de mais peso */
function sealBox(it, compacto){
  const s = sealOf(it), m = seloMarcas(it);
  const sub = s.sc!==null ? `Nota ${s.sc} de 100${it.fontePub ? " · da fonte citada" : ""}` : it.autoral ? (it.autoralSub || AUTORAL[it.autoral][0]) + " · declarada pela autora"
    : it.fontePub && it.fontePub.situacao==="avaliacao" ? esc(it.fontePub.dominio) + " · em avaliação pela curadoria" : it.fontePub && it.fontePub.situacao==="recusada" ? esc(it.fontePub.dominio) + " · avaliada pela curadoria"
    : it.conta && s.label==="Sem fonte" ? "Publicada sem link de fonte" : (s.lv==="pend" ? "Publicação original, ainda não verificada" : it.arte ? "Arte e expressão" : it.daRede ? "Crítica, gosto ou coleção" : "Pergunta, pedido ou opinião");
  return `<details class="sealbox${compacto?" sbmini":""}" ${s.lv==="bad"?"open":""}><summary>${sealIco(s,compacto?22:26)}<span class="t"><b>${s.label}</b><small>${sub}</small></span><span class="linkbtn">Detalhes</span>
    ${m.length ? `<span class="sbmarcas">${m.map(x=>`<span class="sbm" data-m="${x.k}">${ic(x.ic,"sm")}<span class="sbt">${x.t}</span>${x.d ? `<span class="sbd"> · ${esc(x.d)}</span>` : ""}</span>`).join("")}</span>` : ""}</summary>
    ${s.sc!==null?`<div class="scale" role="img" aria-label="Nota ${s.sc} de 100"><i style="left:${s.sc}%"></i></div><div class="scalelbl"><span>Baixa</span><span>Moderada</span><span>Alta</span></div>`:""}
    ${m.length ? `<ul class="sbexp">${m.map(x=>`<li data-m="${x.k}">${ic(x.ic,"sm")}<span>${x.k==="dono" ? "" : `<b>${x.t}</b> `}${x.x}</span></li>`).join("")}</ul>` : ""}
    <p class="sbaviso">A nota é uma avaliação da rede.online, por critérios públicos e iguais para todas as fontes. Não é uma acusação e pode estar errada. <a href="#termos">Como funciona e como pedir revisão</a></p>
    <div class="checks">${sealChecks(it)}</div>
    <p class="note" style="margin:10px 0"><span>Verificação automática com fontes públicas. Se alguém contesta, uma segunda verificação, independente, refaz a análise. O selo avalia fatos, nunca opiniões.</span></p>
    ${it.ext && it.ext.verif.length ? `<div class="vsrc"><b>${ORG[it.org].fonte ? "A mesma notícia em outras fontes" : "Fontes que confirmam"}</b>${it.ext.verif.map(v=>`<a href="${v.url}" target="_blank" rel="noopener"><span>${esc(v.fonte)}<small>${esc(v.papel||"")}${v.o_que_confirma?" · "+esc(v.o_que_confirma):""}</small></span>${ic("ext","sm")}</a>`).join("")}</div>`
      : it.ext && s.sc!==null && !it.daRede ? `<p class="note" style="margin:0 0 10px"><span>Nenhuma fonte da base confirmou este conteúdo ainda.</span></p>` : ""}
    <div class="row"><button class="btn ghost" type="button" data-act="contest">Contestar</button></div></details>`;
}

/* =====================================================================
   5. Arte placeholder (no lugar das fotos)
   ===================================================================== */
function art(item, h=1, label){
  if (item.arte && item.foto && !item.fotoFalhou) return `<span class="arteimg"><img src="${esc(item.foto)}" alt="${label===false ? "" : esc(item.titulo||"")}" loading="lazy" decoding="async" referrerpolicy="no-referrer"></span>`;   /* arte de verdade: a peça inteira, sem corte */
  const nid = typeof item.id==="number" ? item.id : [...String(item.id)].reduce((s,c)=>s + c.charCodeAt(0), 0);
  const [a,b] = PALETTES[nid % PALETTES.length]; const H = Math.round(100*h); let g = "";
  if (item.art==="circles"){ for(let i=0;i<5;i++) g+=`<circle cx="${15+i*18}" cy="${H*(.3+.12*(i%3))}" r="${12+i*4}" fill="${i%2?a:"none"}" stroke="${a}" stroke-width="2.5" opacity="${.5+i*.1}"/>`; }
  else if (item.art==="grid"){ for(let x=0;x<6;x++) for(let y=0;y<Math.ceil(H/16);y++){ const on=(x*7+y*3+nid)%5===0; g+=`<rect x="${4+x*16}" y="${4+y*16}" width="12" height="12" rx="3" fill="${on?a:"none"}" stroke="${a}" stroke-width="1.2" opacity="${on?1:.45}"/>`; } }
  else if (item.art==="arcs"){ for(let i=0;i<7;i++) g+=`<path d="M-10 ${H+10} A ${20+i*14} ${20+i*14} 0 0 1 ${30+i*28} ${H+10}" fill="none" stroke="${a}" stroke-width="${3+i%3}" opacity="${1-i*.1}"/>`; }
  else if (item.art==="stripes"){ for(let i=0;i<14;i++) g+=`<rect x="${i*8}" y="0" width="4" height="${H}" fill="${a}" opacity="${(i%4)/4+.2}" transform="skewX(-12)"/>`; }
  else g+=`<rect x="8" y="${H*.15}" width="40" height="${H*.5}" rx="6" fill="${a}"/><rect x="54" y="${H*.35}" width="38" height="${H*.5}" rx="6" fill="none" stroke="${a}" stroke-width="2.5"/><rect x="20" y="${H*.72}" width="22" height="${H*.18}" rx="4" fill="${a}" opacity=".5"/>`;
  const aria = label===false ? 'aria-hidden="true"' : `role="img" aria-label="Imagem ilustrativa: ${esc(item.titulo||"")}"`;
  return `<svg class="art" viewBox="0 0 100 ${H}" preserveAspectRatio="xMidYMid slice" ${aria}><rect width="100" height="${H}" fill="${b}"/>${g}</svg>`;
}
/* VÍDEOS DE CANAIS DO YOUTUBE (10 nov 2026): a capa é a miniatura do próprio YouTube; o vídeo toca aqui, no player do YouTube
   sem cookies de rastreio (youtube-nocookie), quando a pessoa toca no play; antes disso, uma prévia curta e sem som (ver PRÉVIA DOS VÍDEOS). Um vídeo por vez: tocar outro, ou rolar para longe, para o anterior. */
const ytCapa = (it, h=.5625) => `<span class="ytcapa" data-yt="${it.yt}">${art(it, h, false)}${it.capa ? `<img src="${esc(it.capa)}" alt="" loading="lazy" decoding="async" referrerpolicy="no-referrer">` : ""}</span>`;
const ytPlayBtn = (it, big) => big ? `<button class="ytplay big" type="button" data-act="ytplay" data-yt="${it.yt}" aria-label="Assistir aqui: ${esc(it.titulo)}">${ic("play")}<span>Assistir</span></button>`
  : `<button class="ytplay" type="button" data-act="ytabre" aria-label="Assistir e ver detalhes: ${esc(it.titulo)}">${ic("play")}<span>Assistir</span></button>`;
/* tocar um cartão de vídeo do YouTube (a capa, o botão Assistir ou o bloco) abre o vídeo com os detalhes, e o vídeo já começa */
document.addEventListener("click", e=>{ const f = e.target.closest && e.target.closest(".face.yt, .tbtn, .facewrap .ytplay"); if (!f) return;
  const c = (f.closest(".facewrap") || f).querySelector(".ytcapa[data-yt]"); if (c) S.ytAuto = c.dataset.yt; }, true);
function ytAutoInicia(){ const box = $(".ytbox[data-auto]"); if (!box) return; box.removeAttribute("data-auto"); S.ytAuto = null;
  const b = box.querySelector(".ytplay"); if (b) ytToca(box, b.dataset.yt, b.getAttribute("aria-label").replace(/^Assistir aqui: /,"")); }
/* PRÉVIA DOS VÍDEOS (10 nov 2026): quando a capa de um vídeo do YouTube fica na tela por um instante, ele toca sozinho
   por alguns segundos, sem som e sem clique, e a capa volta. Uma prévia por vez, uma vez por vídeo a cada visita.
   Respeita "Reproduzir vídeos automaticamente" (Configurações), o pedido de menos movimento do aparelho e a economia de dados.
   A prévia não conta na cota de vídeos: a cota vale para quem toca em Assistir. Tocar no cartão abre o vídeo normalmente, com som.
   Atenção (privacidade): com a prévia, o player do YouTube (sem cookies) é carregado sem clique; quem desliga a reprodução automática volta ao comportamento anterior. */
const PREV = {seg:5, el:null, t:0, vistos:new Set(), naTela:new Set(), espera:new WeakMap(), obs:null, olhados:new WeakSet()};
const prevPode = () => S.autoplay && !matchMedia("(prefers-reduced-motion: reduce)").matches && !(navigator.connection && navigator.connection.saveData) && document.visibilityState==="visible";
function prevPara(){ clearTimeout(PREV.t); const e = PREV.el; if (!e) return; PREV.el = null; if (e._msg) removeEventListener("message", e._msg);
  e.classList.remove("on"); setTimeout(()=>e.remove(), 260); setTimeout(prevProxima, 900); }
function prevProxima(){ if (PREV.el || !prevPode()) return; for (const c of PREV.naTela) if (c.isConnected && !PREV.vistos.has(c.dataset.yt)) return prevToca(c); }
function prevToca(capa){ const id = capa.dataset.yt;
  if (!id || PREV.el || PREV.vistos.has(id) || !prevPode() || !capa.isConnected || $(".ytframe, .lvframe") || capa.closest(".ytvivo")) return;
  PREV.vistos.add(id);
  const box = document.createElement("span"); box.className = "ytprev"; box.setAttribute("aria-hidden", "true");
  box.style.setProperty("--w", capa.clientWidth + "px"); box.style.setProperty("--h", capa.clientHeight + "px");
  const web = /^https?:$/.test(location.protocol), orig = web ? "&origin=" + encodeURIComponent(location.origin) : "";
  box.innerHTML = `<iframe src="https://www.youtube-nocookie.com/embed/${encodeURIComponent(id)}?autoplay=1&mute=1&controls=0&playsinline=1&rel=0&modestbranding=1&disablekb=1&fs=0&iv_load_policy=3&enablejsapi=1${orig}" title="" tabindex="-1" allow="autoplay; encrypted-media" referrerpolicy="strict-origin-when-cross-origin"></iframe><span class="ptag">Prévia · sem som</span>`;
  capa.appendChild(box); PREV.el = box; const fr = box.firstChild; let tocando = false;
  const mostra = () => { if (PREV.el!==box || tocando) return; tocando = true; box.classList.add("on"); clearTimeout(PREV.t); PREV.t = setTimeout(prevPara, PREV.seg * 1000); };
  /* o player avisa quando o vídeo começa de fato (ou quando não pode ser embutido): só então a capa dá lugar à prévia */
  box._msg = ev => { if (ev.source!==fr.contentWindow) return; let d = ev.data; try{ if (typeof d==="string") d = JSON.parse(d); }catch(e){ return; }
    if (!d) return; if (d.event==="onError") return prevPara(); if ((d.info && d.info.playerState===1) || (d.event==="onStateChange" && d.info===1)) mostra(); };
  addEventListener("message", box._msg);
  fr.addEventListener("load", ()=>{ const fala = o => { try{ fr.contentWindow.postMessage(JSON.stringify(o), "https://www.youtube-nocookie.com"); }catch(e){} };
    fala({event:"listening", id:"prev", channel:"widget"}); fala({event:"command", func:"addEventListener", args:["onStateChange"], id:"prev", channel:"widget"}); fala({event:"command", func:"addEventListener", args:["onError"], id:"prev", channel:"widget"});
    setTimeout(()=>{ if (!tocando && PREV.el===box) (web ? prevPara : mostra)(); }, web ? 4500 : 1500); });   /* sem resposta do player: no site, desiste; na cópia local, mostra mesmo assim */
  PREV.t = setTimeout(prevPara, 10000); }
function prevObserva(){ if (!PREV.obs) PREV.obs = new IntersectionObserver(es=>es.forEach(e=>{ const c = e.target;
    if (e.isIntersecting && e.intersectionRatio >= .6){ PREV.naTela.add(c); if (!PREV.espera.get(c)) PREV.espera.set(c, setTimeout(()=>{ PREV.espera.delete(c); if (PREV.naTela.has(c)) prevToca(c); }, 700)); }
    else { PREV.naTela.delete(c); clearTimeout(PREV.espera.get(c)); PREV.espera.delete(c); if (PREV.el && PREV.el.parentNode===c && e.intersectionRatio < .3) prevPara(); } }), {threshold:[0, .3, .6]});
  $$(".ytcapa[data-yt]").forEach(c=>{ if (PREV.olhados.has(c) || c.closest(".ytbox")) return; PREV.olhados.add(c); PREV.obs.observe(c); });
  for (const c of PREV.naTela) if (!c.isConnected) PREV.naTela.delete(c); }
let prevRaf = 0;
new MutationObserver(()=>{ if (prevRaf) return; prevRaf = requestAnimationFrame(()=>{ prevRaf = 0; prevObserva(); }); }).observe(document.getElementById("main"), {childList:true, subtree:true});
document.addEventListener("visibilitychange", ()=>{ if (document.visibilityState!=="visible") prevPara(); });
/* 16/11 (Amanda): quem volta depois de 30 minutos ou mais, numa tela de leitura, recomeça no Início, no topo e com conteúdo novo.
   Telas de preencher (criar, anunciar, conta…) ficam como estavam, para ninguém perder o que estava escrevendo. */
let SAIU_EM = 0;
function voltaDepoisDeTempo(){ if (!SAIU_EM || Date.now() - SAIU_EM < 30*60000 || PREVIA){ SAIU_EM = 0; return; } SAIU_EM = 0;
  const r = route(), leitura = r==="" || r==="inicio" || r==="explorar" || r==="organizacoes" || /^(pin|org|pg|pessoa|n)-/.test(r);
  if (!leitura) return;
  sessionStart = Date.now(); F.fixos = null; F.manter = false; F.key = null; closeSheet && closeSheet();
  if (r!=="inicio"){ try{ history.replaceState(null, "", "#inicio"); }catch(e){} }
  render(); window.scrollTo(0, 0); if (SB && typeof noticiasCarrega==="function") noticiasCarrega(); }
document.addEventListener("visibilitychange", ()=>{ if (document.visibilityState==="hidden") SAIU_EM = Date.now(); else voltaDepoisDeTempo(); });
window.addEventListener("pageshow", e=>{ if (e.persisted) voltaDepoisDeTempo(); });
function ytPara(exceto){ if (typeof LV_ON!=="undefined" && LV_ON) vivoFecha(); $$(".ytframe").forEach(fr=>{ if (exceto && exceto.contains(fr)) return; const box = fr.parentNode; fr.remove(); box.classList.remove("ytvivo"); }); }
/* cota de vídeos: visitante, 8 por visita; conta com e-mail, 15 a cada 12 horas e depois só no canal original */
