  if (nav){ tipo = "nav"; nome = usoRota(nav.dataset.navTo); }
  else if (b && !(b.dataset.act === "closebg" && t !== b)){ tipo = "toque"; nome = b.dataset.act; }
  else if (lk){ const h = lk.getAttribute("href") || ""; if (h.startsWith("#")){ tipo = "nav"; nome = usoRota(h.slice(1)); } else { tipo = "saida"; try{ nome = new URL(lk.href).hostname.replace(/^www\./, "").slice(0, 60); }catch(err){ nome = "link"; } } }
