    const artes = fvOrdena(l.filter(it=>it.daArte).concat(POOL.filter(it=>it.daArte && !vistas.has(it.id) && passa(it, fl)).sort((a,b)=>a.min-b.min)));
    if (artes.length){ const out = []; let k = 0; resto.forEach((it,i)=>{ out.push(it); if ((i + 1) % ARTE_CADA === 0 && k < artes.length) out.push(artes[k++]); }); l = out; }
