/* se a tela ainda não encheu (sentinela visível), carrega mais sem esperar a rolagem */
function fillViewport(){ const st = $("#sentinel"); if (!st || F.paused || F.ended || route()!=="inicio") return;
  if (st.getBoundingClientRect().top < innerHeight + 800) more(10); }
/* mobile first, mas responsivo: o número de colunas das abas de lista acompanha a largura do feed */
function feedCols(L){ const w = ($("#feed") || document.body).clientWidth || innerWidth;
  if (L==="agenda") return w >= 900 ? 3 : 2;
  if (L==="video") return 1;                       /* regra: a aba Vídeos é sempre uma coluna */
  if (L==="masonry") return w >= 900 ? 3 : 2;      /* cartões soltos: duas colunas no celular, como em "Mais para explorar" */
  if (L==="arquivo") return w >= 1100 ? 4 : w >= 720 ? 3 : 2;   /* documentos: cartões compactos, mais de um por linha (12 nov 2026) */
  return w >= 720 ? 2 : 1; }
function resetFeed(){
  altaFaixa(); docBase(); aoVivo();
  const manter = F.manter && F.items.length; F.manter = false;
  if (manter){ const vis = F.items.filter(i=>!i.base && !S.created.includes(i)); F.fixos = vis.map(i=>String(i.id)); F.fixosObj = Object.fromEntries(vis.map(i=>[String(i.id), i])); } else { F.fixos = null; F.fixosObj = {}; }
  const nAntes = manter ? F.fixos.length : 0;
  F.items = []; F.cursor = 0; F.vistos = 0; F.gate = null; F.paused = false; F.ended = false; F.key = feedKey();
  wrapClass(); const L = feedLayout();
  F.grid = L==="blocos" ? new TileGrid("feed", $("#feed"), feedMode()) : new Grid("feed", $("#feed"), feedMode(), feedCols(L), L);
  F.grid.arte = S.tab==="arte";
  const types = tabTypes(); S.created.slice().reverse().forEach(c=>{ if(!types || types.includes(c.tipo)){ F.items.push(c); F.grid.add(c); } });
  F.grid.render(); more(Math.max(12, nAntes));
}
/* avisos do feed: discretos, centralizados, sem bloco pesado */
function renderStop(){
  const box = $("#stop"); if(!box) return;
  if (F.gate){ box.innerHTML = gateNota(F.gate); return; }
  const mins = Math.max(1, Math.round((Date.now()-sessionStart)/60000));
  const nome = (FTABS.find(t=>t[0]===S.tab)||FTABS[0])[1].toLowerCase(), nf = nFiltros();
  const note = (msg, acts) => `<div class="endnote" role="status"><p>${msg}</p><div class="acts">${acts}</div></div>`;
  const clear = nf ? `<button class="linkbtn" type="button" data-act="fclearnow">Limpar filtros</button>` : "";
  const all = S.tab!=="tudo" ? `<button class="linkbtn" type="button" data-act="ftab" data-tab="tudo">Ver tudo</button>` : "";
  const RQ = S.rapido && RAPIDOS.find(r=>r[0]===S.rapido), sair = RQ ? `<button class="linkbtn" type="button" data-act="rapido" data-k="${S.rapido}">Tirar “${RQ[1]}”</button>` : "";
  if (RQ && F.ended){ const R = minhaRegiao(), tab = S.tab!=="tudo" ? " em " + nome : "";
    const msg = S.rapido==="perto" && !R.cidade && !R.uf ? `<b>Diga sua cidade.</b> Assim aparece o que acontece perto de você.`
      : S.rapido==="desmentidos" ? (F.cursor ? `<b>Esses são os desmentidos${tab}.</b> Vêm das agências de checagem da base, como Aos Fatos, Projeto Comprova e AFP Checamos, nas línguas que você escolheu em Origens.` : `<b>Nenhum desmentido${tab} agora.</b> Eles vêm das agências de checagem da base, nas línguas que você escolheu em Origens.`)
      : S.rapido==="alta" ? (F.cursor ? `<b>Isso é o que está em alta${tab}.</b> Últimas 72 horas, pela repercussão.` : `<b>Nada em alta${tab} nas últimas 72 horas.</b>`)
      : (F.cursor ? `<b>Isso é o que acontece perto de você${tab}.</b> ${esc(R.txt || "")}` : `<b>Nada perto de você${tab} agora.</b> ${esc(R.txt || "")}`);
    const extra = S.rapido==="perto" ? `${R.cidade || R.uf ? "" : `<button class="linkbtn" type="button" data-act="localpede">Usar minha localização</button>`}<button class="linkbtn" type="button" data-act="origens">${R.cidade || R.uf ? "Mudar a cidade" : "Definir a cidade"}</button>` : S.rapido==="desmentidos" ? `<button class="linkbtn" type="button" data-act="origens">Origens</button>` : "";
    box.innerHTML = note(msg, extra + sair); return; }
  if (F.ended && F.cursor>0) box.innerHTML = note(`<b>${S.tab==="tudo" && !nf ? "Você está em dia." : "Você viu tudo" + (S.tab!=="tudo" ? " em " + nome : "") + "."}</b> ${nf ? "Com os filtros atuais, não há mais conteúdo." : S.tab==="tudo" ? "Notícias novas chegam ao longo do dia. O que você já viu não volta para o começo." : "Quando suas comunidades publicarem mais, aparece aqui."}`, all + clear);
  else if (F.ended) box.innerHTML = note(`<b>Nada por aqui ainda.</b> ${nf?"Nenhum conteúdo combina com os filtros.":S.tab==="arte" ? (SB && !ME.offline ? "As artes do acervo do Design Ativista aparecem aqui depois de aprovadas pela curadoria." : "As artes vêm do servidor. Sem conexão agora.") : "Ainda não há publicações deste tipo."}`, all + clear);
  else if (F.paused) box.innerHTML = note(`<b>Pausa.</b> Você viu ${F.cursor} publicações em ${mins} min.`, `<button class="linkbtn" type="button" data-act="continue">Continuar</button><button class="linkbtn muted" type="button" data-act="endsession">Encerrar por hoje</button>`);
  else box.innerHTML = `<div class="loading">Carregando mais…</div>`;
}

