function vitBoard(x, f){ const l = f.itens.map(vitVer), n = l.length, sl = l.slice(0, 6);
  const capa = !n ? `<span class="bmini"><span class="bempty">${ic("bookmark")}</span></span>`
    : `<span class="bmini bcar" aria-hidden="true"><span class="bcartrack">${sl.map(slideDe).join("")}</span>${sl.length > 1 ? `<span class="bdots">${sl.map((y, i)=>`<i${i ? "" : ' class="on"'}></i>`).join("")}</span><span class="bcarseta ant" data-act="bcarpassa" data-d="-1" role="button" aria-label="Anterior">${ic("back","sm")}</span><span class="bcarseta prox" data-act="bcarpassa" data-d="1" role="button" aria-label="Próxima">${ic("back","sm flip")}</span>` : ""}</span>`;
  return `<button class="board" type="button" data-act="vpasta" data-s="${esc(x.id)}" data-f="${esc(f.k)}">${capa}<b>${esc(f.nome)}</b><small>${n} ${n===1 ? "item" : "itens"}</small></button>`; }
function vitCard(x){ const it = vitVer(x), h = hashN(String(x.id));
  const corpo = `<span class="mfoto">${it.foto ? `<img src="${esc(it.foto)}" alt="" loading="lazy" referrerpolicy="no-referrer">` : art({id:h, art:CAPAS[h % 5]}, .45, false)}</span>
    <span class="mtx"><b>${esc(it.titulo || "")}</b>${x.org || (ORG[it.org] || {}).nome ? `<span class="mquem">${esc(x.org || ORG[it.org].nome)}</span>` : ""}</span>`;
  return it._rede ? `<a class="mcard" href="#pin-${esc(String(it.id))}-0">${corpo}</a>` : x.url ? `<a class="mcard" href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${corpo}</a>` : `<div class="mcard">${corpo}</div>`; }
function pessPastasHTML(uid){ const l = PESS_PASTAS[uid]; if (!l){ pessPastasCarrega(uid); return `<p class="empty">Carregando…</p>`; }
  if (!l.length) return `<p class="empty">Nenhuma pasta à mostra.</p>`;
  const v = S.vPasta && S.vPasta.u === uid ? S.vPasta : null, x = v && l.find(y=>y.id === v.s), f = x && x.pastas.find(y=>y.k === v.f);
  if (f) return `<div class="status"><button class="iconbtn tool" type="button" data-act="vpasta" data-s="" aria-label="Voltar para as pastas">${ic("back")}</button><span class="txt"><b>${esc(f.nome)}</b> · ${esc(x.nome)} · ${f.itens.length} ${f.itens.length===1 ? "item" : "itens"}</span></div>
    ${(()=>{ if (!f.itens.length) return `<p class="empty">Pasta vazia.</p>`;   /* o que existe na rede usa a mesma grade do feed; o resto, cartão com link de origem */
      const aqui = f.itens.filter(i=>vitVer(i)._rede), fora = f.itens.filter(i=>!vitVer(i)._rede);
      return (aqui.length ? `<div data-mas="${esc(aqui.map(i=>String(i.id)).join(","))}"></div>` : "") + (fora.length ? `<div class="cmngrid orgblocos" style="margin-top:var(--gap)">${fora.map(vitCard).join("")}</div>` : ""); })()}`;
  return l.map(x=>`<section class="psecao" aria-label="Seção ${esc(x.nome)}"><div class="psechead"><h3>${esc(x.nome)}</h3><span class="psecn">${x.pastas.length} ${x.pastas.length===1 ? "pasta" : "pastas"}</span></div>
    <div class="pboards prow" role="list">${x.pastas.map(f=>vitBoard(x, f)).join("")}</div></section>`).join(""); }
function screenPublic(){
  const orgs = ORGS.filter(o=>S.follow.has(o.id));
  const pf0 = (ME.user && ME.perfil) || {};
  return header(`<div class="toprow">${topoLugar(perfilTag(true), `<button class="iconbtn" type="button" aria-disabled="true" data-act="segprevia" aria-label="Seguir (é assim que outras pessoas veem)" title="Seguir">${ic("seguir")}</button><button class="iconbtn" type="button" data-act="share" data-perfil="${pf0.id ? "u-" + pf0.id : ""}" aria-label="Compartilhar o perfil" title="Compartilhar">${ic("share")}</button>`)}</div>`)
  + `<div class="container">
    ${(()=>{ const pf = (ME.user && ME.perfil) || {nome:"Você"}, vis = `<button class="phvis" type="button" data-act="visdet" aria-haspopup="dialog" aria-label="Perfil ${S.publico ? "público" : "privado"}: ver o que aparece" title="Perfil ${S.publico ? "público" : "privado"}">${ic(S.publico ? "cadaberto" : "lock","sm")}</button>`;
      const chips = S.interesses.map(t=>`<span class="chip static">${esc(t)}</span>`).join("") + (S.orgsVisiveis ? orgs.map(o=>`<span class="chip static">${ic("people","sm")}${esc(o.nome)}</span>`).join("") : "") + (ME.user ? pgChips(ME.user.id) : "");
      return pessoaHead({nome:pf.nome, verificado:pf.verificado, meta:pf.cidade ? esc(pf.cidade) : "", bio:pf.bio,
        chips}); })()}
    <div class="tabs pubtabs" role="tablist" aria-label="Perfil público">${[["publicacoes","Publicações"],["pastas","Pastas"],["redes","Outras redes"]].map(([k,n])=>`<button class="tab" type="button" role="tab" data-act="pubtab" data-tab="${k}" aria-selected="${S.pubTab===k}">${n}${tabVis(S.publico && (k!=="pastas" || pubFolders().length > 0))}</button>`).join("")}</div>
    <div class="status" id="pubstatus"${pubStatus() ? "" : " hidden"}>${pubStatus()}</div>
    <div id="pubbody">${pubBody()}</div></div>`;
}
/* MOBILIZAR: a notícia acende a conversa; daqui sai um evento, um chamado, um abaixo-assinado ou uma votação, já ligados à matéria */
const MOBS = [["evento","Evento","clock"],["chamado","Chamado","hand"],["abaixo","Abaixo-assinado","doc"],["votacao","Votação","lock"]];
const mobsOf = it => S.created.filter(c=>c.ref===it.id);
function mobBox(it){ const l = mobsOf(it);
  return `<section class="pinsec mob"><button class="btn block mobopen" type="button" data-act="mobopcoes" data-id="${it.id}">${ic("hand","sm")} Mobilizar a partir disto</button>
    ${l.length ? `<p class="lnote">${l.length} ${l.length===1?"mobilização ligada":"mobilizações ligadas"} a esta notícia: ${l.map(c=>`<button class="linkbtn" type="button" data-act="open" data-uid="${c.uid}">${esc(c.titulo)}</button>`).join(", ")}</p>` : ""}</section>`; }
function sheetMobilizar(id){ const it = POOL.find(p=>String(p.id)===String(id)); if (!it) return;
  openSheet(shead("Mobilizar a partir disto") + `
    <p class="lnote" style="margin:0 0 12px">O que você criar fica ligado a esta notícia: ${esc(it.titulo)}</p>
    ${it.gancho ? `<p class="mobhook">${ic("info","sm")}<span>${esc(it.gancho)}</span></p>` : ""}
    <div class="mobbtns">${MOBS.map(([k,n,i])=>`<button class="btn" type="button" data-act="mobilizar" data-k="${k}" data-id="${it.id}">${ic(i,"sm")} ${n}</button>`).join("")}</div>`, "Mobilizar a partir disto"); }
/* participação que acontece fora da rede (processo público real): mostra o essencial e leva ao site oficial */
function extBox(it, label, body, facts){ facts = (facts||[]).filter(Boolean);
  return `<div class="pinsec">${facts.length?`<div class="facts">${facts.map(([k,v])=>`<div class="fact"><b>${esc(v)}</b>${k}</div>`).join("")}</div>`:""}${body}
    <a class="btn primary block" href="${it.ext.url}" target="_blank" rel="noopener" style="margin-top:10px">${label} ${ic("ext","sm")}</a>
    <p class="lnote" style="margin-top:8px">Processo público fora da rede: a participação acontece no site oficial.</p></div>`; }
function interact(it){
  const uid = it.uid;
  switch(it.tipo){
    case "evento": { const r = S.rsvp[uid];
      return `<div class="pinsec"><div class="row" style="font-size:14px;color:var(--muted);gap:14px;margin-bottom:10px"><span style="display:inline-flex;gap:6px;align-items:center">${ic("clock","sm")}${it.dia} ${it.mes}, ${it.hora}</span><span style="display:inline-flex;gap:6px;align-items:center">${ic("pin","sm")}${it.local}</span></div>
        <div class="row"><button class="btn" type="button" data-act="rsvp" data-uid="${uid}" data-v="vou" aria-pressed="${r==="vou"}">${r==="vou"?ic("check","sm")+" Vou":ic("calplus","sm")+" Quero ir"}</button><button class="btn" type="button" data-act="rsvp" data-uid="${uid}" data-v="talvez" aria-pressed="${r==="talvez"}">Talvez</button></div>
        <p style="font-size:13px;color:var(--muted);margin-top:8px">${vaoOf(it)} pessoas confirmadas</p></div>`; }
    case "enquete": if (it.externo) return extBox(it, "Responder no site oficial", `${it.pergunta?`<p class="pinbody" style="margin:0 0 8px"><b>${esc(it.pergunta)}</b></p>`:""}${it.opcoes.length?`<ul class="xopts">${it.opcoes.map(o=>`<li>${esc(o)}</li>`).join("")}</ul>`:""}`, [it.fecha && ["Prazo", it.fecha]]);
    { const mine = S.pollVote[uid]; const votos = it.votos.map((v,i)=>v+(mine===i?1:0)); const tot = votos.reduce((a,b)=>a+b,0);
      return `<div class="pinsec opts">${it.opcoes.map((op,i)=>{ const pct = Math.round(votos[i]/tot*100);
        return mine===undefined ? `<button class="opt" type="button" data-act="poll" data-uid="${uid}" data-i="${i}"><span>${op}</span></button>`
          : `<div class="opt ${mine===i?"mine":""}"><i class="fill" style="width:${pct}%"></i><span>${op}${mine===i?" ✓":""}</span><span style="font-variant-numeric:tabular-nums">${pct}%</span></div>`; }).join("")}
        <p style="font-size:13px;color:var(--muted)">${tot} votos · consulta aberta, não vale como decisão</p></div>`; }
    case "votacao": if (it.externo) return extBox(it, "Participar no site oficial", `${it.decide?`<p class="pinbody" style="margin:0 0 8px">${esc(it.decide)}</p>`:""}${it.opcoes.length?`<ul class="xopts">${it.opcoes.map(o=>`<li>${esc(o)}</li>`).join("")}</ul>`:""}`, [it.quemVota && ["Quem vota", it.quemVota], it.prazo && ["Prazo", it.prazo]]);
    { if (it.fase==="apoios"){ const a = supState(it);
        return `<div class="pinsec"><div class="facts"><div class="fact"><b>${a.a} de ${a.meta}</b>apoios</div><div class="fact"><b>20%</b>dos ${it.votantes} com voto</div></div>
          <div class="bar" style="margin:12px 0" role="img" aria-label="${a.pct}% dos apoios necessários"><i style="width:${a.pct}%;background:${ORG[it.org].cor}"></i></div>
          <p style="font-size:13px;color:var(--muted);margin-bottom:10px">Quando atingir 20% dos membros com direito a voto, a proposta vira votação automaticamente.${it.autor?` Proposta de ${it.autor}.`:""}</p>
          <button class="btn block" type="button" data-act="apoiar" data-uid="${uid}" aria-pressed="${a.on}">${a.on?ic("check","sm")+" Você apoiou":"Apoiar a proposta"}</button></div>`; }
      const st = voteState(it), done = st.done, v = st.v, pct = st.pct;
      return `<div class="pinsec"><div class="facts"><div class="fact"><b>${v} de ${it.votantes}</b>já votaram</div><div class="fact"><b>Quórum ${it.quorum}</b>${v>=it.quorum?"atingido":"ainda não"}</div><div class="fact"><b>Voto secreto</b>auditável</div><div class="fact"><b>Encerra</b>em ${it.prazo}</div></div>
        <p class="lnote" style="margin-top:8px">${procLine(it)}</p>
        <div class="bar" style="margin:12px 0" role="img" aria-label="${pct}% dos votantes já votaram"><i style="width:${pct}%"></i></div>
        ${done ? `<button class="btn block" type="button" disabled>${ic("check","sm")} Você já votou</button>` : `<button class="btn primary block" type="button" data-act="formal" data-uid="${uid}">${ic("lock","sm")} Votar</button>`}</div>`; }
    case "chamado": if (it.ext && !it.meta) return extBox(it, "Participar na fonte original", "", [["O que", it.un], it.quando && ["Prazo", it.quando], it.como && ["Como", it.como]]);
    { const on = S.help[uid]; const t = it.tem + (on?1:0);
      return `<div class="pinsec"><div class="bar" role="img" aria-label="${t} de ${it.meta}"><i style="width:${Math.min(100,Math.round(t/it.meta*100))}%;background:${ORG[it.org].cor}"></i></div>
        <p style="font-size:13.5px;margin:6px 0 10px;font-variant-numeric:tabular-nums"><b>${t}</b> de ${it.meta}</p>
        <button class="btn block" type="button" data-act="help" data-uid="${uid}" aria-pressed="${!!on}">${ic("hand","sm")} ${on?"Você está dentro":"Quero ajudar"}</button></div>`; }
    case "documento": return it.ext ? ""
      : `<div class="pinsec"><div class="native">${ic("doc","sm")}<span>Documento de exemplo · ${it.pags} pág. Não há arquivo para abrir.</span><span class="fic">exemplo</span></div></div>`;
    case "video": return it.yt ? "" : it.ext ? `<div class="pinsec"><a class="btn primary block" href="${it.ext.url}" target="_blank" rel="noopener">${ic("play","sm")} ${"Assistir " + (it.plat?"no "+esc(it.plat):"na fonte")}${it.dur?` · ${it.dur}`:""} ${ic("ext","sm")}</a></div>` : "";
    default: return "";
  }
}
/* PARA ENTENDER E CONVERSA (10 nov 2026), no detalhe do cartão.
   PARA ENTENDER: uma nota curta que explica algo ligado ao conteúdo (por exemplo, quem responde pela segurança pública),
   com a fonte oficial. Não aparece sempre: só quando o assunto pede e a confiança é alta. Quem decide e escreve é o servidor
   (função "entender"), sempre a partir de notas aprovadas pela curadoria; a fonte mostrada vem dessa base, nunca da IA.
   CONVERSA: comentários. Só quem tem conta comenta; todo mundo lê. O comentário mostra o nome do perfil (aviso no primeiro uso).
   Comentários de usuário colaborador, ou marcados como úteis por várias pessoas, sobem como "Em destaque".
   Muita conversa e comentários muito marcados como úteis dizem à rede onde prestar atenção: é o que faz o servidor
   reavaliar se aquele conteúdo merece um Para entender. Contribuições com fonte (confirma ou contesta) viram sinais
   que a curadoria revisa antes de mexer no selo. Tudo o que vem de pessoas é escapado antes de ir para a tela. */
const uuidDe = h => h.replace(/^(.{8})(.{4})(.{4})(.{4})(.{12})$/, "$1-$2-$3-$4-$5");
function alvoDe(it){ if (!it || it.exemplo) return null;
  if (it.coletada && /^n[0-9a-f]{32}$/.test(String(it.id))) return {col:"noticia_id", id:uuidDe(String(it.id).slice(1))};
  if (it.conta && it.uuid) return {col:"publicacao_id", id:it.uuid}; return null; }
const pentSlot = it => { const a = alvoDe(it); return a && a.col==="noticia_id" ? `<aside class="pent" data-pent="${a.id}" aria-label="Para entender" hidden></aside>` : ""; };
const comsSlot = it => { const a = alvoDe(it); return a ? `<section class="coms" data-coms="${a.col}:${a.id}" aria-label="Conversa"></section>` : ""; };
const PENT = new Map();
function pentBusca(id){ if (PENT.has(id)) return PENT.get(id);
  const pr = (async () => { if (!SB || ME.offline) return null;
    try{ const r = await SB.from("entender").select("titulo,texto,fonte_nome,fonte_url,origem").eq("noticia_id", id).eq("status","publicada").maybeSingle(); if (!r.error && r.data) return r.data; }catch(e){}
    try{ const r = await fetch(`${SB_URL}/functions/v1/entender?id=${id}`, {headers:{apikey:SB_KEY}}); if (r.ok){ const j = await r.json(); return (j && j.nota) || null; } }catch(e){}
    return null; })();
  PENT.set(id, pr); return pr; }
function pentHTML(n){ const url = /^https:\/\//.test(n.fonte_url || "") ? n.fonte_url : "";
  return `<span class="penth">${ic("info","sm")} Para entender</span><h3>${esc(n.titulo)}</h3><p>${esc(n.texto)}</p>
    <div class="pentf">${url ? `<a href="${esc(url)}" target="_blank" rel="noopener">Fonte: ${esc(n.fonte_nome)} ${ic("ext","sm")}</a>` : `<span>Fonte: ${esc(n.fonte_nome)}</span>`}
      <small>${n.origem==="ia" ? "Escrito por IA a partir de uma nota conferida pela curadoria da rede." : "Nota da curadoria da rede."}</small></div>`; }
async function pentPreenche(el){ el.dataset.ok = "1"; const n = await pentBusca(el.dataset.pent); if (!n || !el.isConnected) return; el.innerHTML = pentHTML(n); el.hidden = false; }

const COMS = new Map(), COM_DEST = 3, MARCAS = {contexto:"Acrescenta contexto", confirma:"Confirma", contesta:"Contesta"};
const comCor = id => CORES_CONTA[parseInt(String(id || "0").replace(/-/g,"").slice(0,6), 16) % CORES_CONTA.length];
async function comsCarrega(key){ const [col, id] = key.split(":"), st = COMS.get(key) || {aberto:false};
  if (!SB || ME.offline){ COMS.set(key, Object.assign(st, {lista:[], meus:new Set(), fora:true})); return; }
  let lista = [], meus = new Set(), erro = false;
  try{ const r = await SB.from("comentarios").select("id,texto,marca,fonte_url,uteis,criado_em,autor,perfis(nome,verificado,colaborador)").eq(col, id).eq("status","publicado").order("criado_em",{ascending:false}).limit(200);
    if (r.error) erro = true; else lista = r.data || [];
    if (ME.user && lista.length){ const u = await SB.from("comentario_uteis").select("comentario_id").in("comentario_id", lista.map(c=>c.id)); if (!u.error) meus = new Set((u.data || []).map(x=>x.comentario_id)); } }catch(e){ erro = true; }
  COMS.set(key, Object.assign(st, {lista, meus, erro, fora:false})); }
const comDest = c => !!((c.perfis || {}).colaborador) || c.uteis >= COM_DEST;
function comHTML(c, st){ const pf = c.perfis || {}, meu = ME.user && c.autor===ME.user.id, adm = ME.perfil && ME.perfil.papel==="admin", dest = comDest(c), url = /^https:\/\//.test(c.fonte_url || "") ? c.fonte_url : "", on = st.meus.has(c.id);
  return `<article class="com${dest ? " dest" : ""}" data-com="${c.id}">
    ${ehContaRede(c.autor) ? `<span class="av cav rede" aria-hidden="true"><span class="amark">a<i></i></span></span>` : `<span class="av cav" style="background:${comCor(c.autor)}" aria-hidden="true">${esc(siglaDe(pf.nome))}</span>`}
    <div class="cb"><div class="comh"><span class="cn">${esc(pf.nome || "Conta da rede")}</span>${verifBtn(pf.verificado)}${pf.colaborador ? `<span class="colab" title="Usuário colaborador: destaque dado pela rede a quem contribui de forma construtiva">Colaborador</span>` : ""}<small>${quando(c.criado_em)}${c.marca && MARCAS[c.marca] ? " · " + MARCAS[c.marca].toLowerCase() : ""}</small>${dest && !pf.colaborador && pf.papel!=="admin" ? `<span class="ctag d">Em destaque</span>` : ""}</div>
      <p class="ctx">${esc(c.texto)}</p>
      ${url ? `<a class="cfonte" href="${esc(url)}" target="_blank" rel="noopener nofollow ugc">Fonte: ${esc(hostOf(url).replace(/^www\./,""))} ${ic("ext","sm")}</a>` : ""}
      <div class="cacts"><button class="linkbtn cutil" type="button" data-act="comutil" data-id="${c.id}" aria-pressed="${on}"${meu ? " disabled" : ""} aria-label="Marcar como útil${c.uteis ? ". " + c.uteis + " pessoas marcaram" : ""}">${ic("heart","sm")} Útil${c.uteis ? " · " + c.uteis : ""}</button>
        ${meu || adm ? `<button class="linkbtn muted" type="button" data-act="comapaga" data-id="${c.id}">${meu ? "Apagar" : "Remover (moderação)"}</button>` : ME.user ? `<button class="linkbtn muted" type="button" data-act="comdenuncia" data-id="${c.id}">${ic("flag","sm")} Denunciar</button>` : ""}</div></div></article>`; }
function comForm(){ if (!ME.user) return `<div class="cnovo fora"><span>Só quem tem conta comenta. Ler é livre.</span><a class="linkbtn" href="#conta" data-act="criarconta">Criar conta</a><a class="linkbtn" href="#conta" data-act="acessar">Entrar</a></div>`;
  return `<div class="cnovo"><textarea class="ctxt" rows="1" maxlength="1000" placeholder="Comente algo construtivo" aria-label="Seu comentário"></textarea>
    <div class="chips cmarcas" role="group" aria-label="Tipo de contribuição, opcional">${Object.entries(MARCAS).map(([k,t])=>`<button class="chip" type="button" data-act="commarca" data-m="${k}" aria-pressed="false">${t}</button>`).join("")}</div>
    <input class="cfon" type="url" inputmode="url" placeholder="Endereço da fonte (https://…)" maxlength="500" aria-label="Endereço da fonte" hidden>
    <div class="caviso" hidden><p><b>Seu comentário é público.</b> Ele aparece com o nome do seu perfil para qualquer pessoa, mesmo com o perfil privado. Você pode apagar quando quiser.</p>
      <div class="row"><button class="btn sm primary" type="button" data-act="comenvia" data-ciente="1">Entendi, comentar</button><button class="btn sm ghost" type="button" data-act="comcancela">Cancelar</button></div></div>
    <p class="rmsg cmsg" role="alert"></p><button class="btn sm primary cbt" type="button" data-act="comenvia">Comentar</button></div>`; }
function comsHTML(key){ const st = COMS.get(key); if (!st || !st.lista) return `<h3 class="pinh">Conversa</h3><p class="cvazio">Carregando…</p>`;
  if (st.fora) return "";
  const L = st.lista.slice().sort((a,b)=>(comDest(b) - comDest(a)) || (comDest(a) ? b.uteis - a.uteis : 0) || (new Date(b.criado_em) - new Date(a.criado_em))), n = L.length, vis = st.aberto ? L : L.slice(0, 4);
  return `<h3 class="pinh">Conversa${n ? " · " + n : ""}</h3>${comForm()}${st.erro ? `<p class="cvazio">Não deu para carregar os comentários agora.</p>` : n ? vis.map(c=>comHTML(c, st)).join("") : `<p class="cvazio">Ninguém comentou ainda.</p>`}
    ${n > vis.length ? `<button class="linkbtn" type="button" data-act="commais">Ver mais ${n - vis.length}</button>` : ""}`; }
/* redesenha sem perder o que a pessoa estava escrevendo */
function comsDesenha(key){ $$(`[data-coms="${key}"]`).forEach(el=>{ const t = el.querySelector(".ctxt"), f = el.querySelector(".cfon"), m = el.querySelector('.cmarcas [aria-pressed="true"]'), r = {t:t ? t.value : "", f:f ? f.value : "", m:m ? m.dataset.m : ""};
    const h = comsHTML(key); el.hidden = !h; el.innerHTML = h;
    const t2 = el.querySelector(".ctxt"); if (t2 && r.t) t2.value = r.t; if (r.m){ const b = el.querySelector(`.cmarcas [data-m="${r.m}"]`); if (b) b.setAttribute("aria-pressed", "true"); const f2 = el.querySelector(".cfon"); if (f2){ f2.hidden = false; f2.value = r.f; } } }); }
async function comsPreenche(el){ el.dataset.ok = "1"; const key = el.dataset.coms; el.innerHTML = comsHTML(key); if (!COMS.has(key) || !COMS.get(key).lista) await comsCarrega(key); if (el.isConnected) comsDesenha(key); }
document.addEventListener("focusin", e=>{ const t = e.target; if (t && t.classList && t.classList.contains("ctxt")) t.closest(".cnovo").classList.add("ativo"); });
document.addEventListener("input", e=>{ const t = e.target; if (t && t.classList && t.classList.contains("ctxt")){ t.style.height = "auto"; t.style.height = Math.min(220, t.scrollHeight + 2) + "px"; } });
const comKey = b => { const s = b.closest("[data-coms]"); return s ? s.dataset.coms : ""; };
