    for (const r of data){ const id = "u-" + r.seguido; if (!S.follow.has(id)){ S.follow.add(id); mudou = true; } }
    for (const id of [...S.follow]) if (ehPessoaReal(id) && !data.some(r=>"u-" + r.seguido === id)){ S.follow.delete(id); mudou = true; }
    try{ const pr = await SB.from("pagina_seguidores").select("pagina_id"); if (pr.data){
      for (const r of pr.data){ const id = "pg-" + r.pagina_id; if (!S.follow.has(id)){ S.follow.add(id); mudou = true; } }
      for (const id of [...S.follow]) if (/^pg-/.test(id) && !pr.data.some(r=>"pg-" + r.pagina_id === id)){ S.follow.delete(id); mudou = true; } } }catch(e){}
