function sealChecksRede(it, L){ const R = REDES[it.rede], o = ORG[it.org], s = sealOf(it);
  let q = L("warn", "Fonte individual", (it.minha ? "Publicado por você" : "Publicado por " + esc(o.nome)) + " no " + R.nome + ", sem verificação editorial. Vale ler junto com outras fontes.");
  q += L("ok", "Perfil público", it.minha ? "Você conectou este perfil. A rede.online lê o feed aberto dele, e nada é publicado lá." : "Lido pelo feed aberto do " + R.nome + ". Só você vê que acompanha este perfil.");
  if (s.lv==="na") q += L("na", "Afirmações checadas", "Crítica, gosto ou coleção: o selo avalia fatos, não opiniões.");
  else q += L(it.ext.verif.length ? "ok" : "warn", "Fontes que confirmam", it.ext.verif.length ? `${it.ext.verif.length} ${it.ext.verif.length===1?"fonte":"fontes"} da base sobre o mesmo assunto: ${it.ext.verif.map(v=>esc(v.fonte)).join(", ")}.` : "Nenhuma fonte da base trouxe o mesmo assunto ainda. A nota sobe quando alguma trouxer.");
  if (it.repost) q += L("warn", "Salvo de outra pessoa", "No Pinterest, o perfil reúne o que a pessoa salvou. A autoria original pode ser de outra pessoa.");
  if (it.exemplo) q += L("na", "Exemplo", "Sem conexão agora: estas publicações são exemplos. As reais chegam quando a internet voltar.");
  return q; }
