if (TESTE_HTML && TESTE_PIN && !S.redes.some(c=>c.rede==="pinterest" && c.tipo==="minha")){ const c = {id:"teste-pinterest", rede:"pinterest", usuario:TESTE_PIN, tipo:"minha", destino:"perfil"}; S.redes.push(c); persist("redes");
  redeAtualiza(c, true).then(r=>{ if (r !== true){ const e = redeExemplos("pinterest", TESTE_PIN); REDE_CACHE[c.id] = {em:Date.now(), itens:e.itens, exemplo:true}; }
    store.set("redesCache", REDE_CACHE); persist("redes"); redesAplica(); if (["perfil-ver","perfil"].includes(route())) render(); }); }

/* =====================================================================
   PEDIDO DE CADASTRO DE ORGANIZAÇÃO: vai para a fila da curadoria (tabela org_pedidos) e só aparece
   na rede depois de aprovado. Quem pede acompanha o andamento aqui mesmo.
   ===================================================================== */
let MEUS_PEDIDOS = null;
const PED_ST = {pendente:["warn","Em análise"], aprovada:["ok","Aprovada"], recusada:["bad","Recusada"]};
async function pedidosCarrega(){ if (!SB || !ME.user) return;
  try{ const r = await SB.from("org_pedidos").select("id,nome,cidade,status,motivo,criada_em").eq("user_id", ME.user.id).order("criada_em", {ascending:false}); if (!r.error) MEUS_PEDIDOS = r.data; }catch(e){}
  const l = $("#pedlista"); if (l) l.outerHTML = pedidosLista(); }
function pedidosLista(){ if (!MEUS_PEDIDOS || !MEUS_PEDIDOS.length) return `<div id="pedlista"></div>`;
  return `<div id="pedlista"><h3 class="osec">Seus pedidos</h3><div class="ogrp">${MEUS_PEDIDOS.map(p=>{ const [c, t] = PED_ST[p.status] || PED_ST.pendente;
    return `<div class="orow"><span class="ot"><b>${esc(p.nome)}</b><small>${esc(p.cidade)} · pedido ${quando(p.criada_em)}${p.motivo ? " · " + esc(p.motivo) : ""}</small></span><span class="pstat ${c}">${t}</span></div>`; }).join("")}</div></div>`; }
function sheetOrgPedido(){ S.pedTema = S.pedTema || "";
  const sem = !SB || ME.offline;
  const corpo = sem ? `<div class="note">${ic("info")}<span>Sem conexão com o servidor agora. O pedido precisa dele para chegar à curadoria. Tente de novo quando a internet voltar.</span></div>`
    : !ME.user ? `<div class="note">${ic("lock")}<span>Para pedir o cadastro, acesse a rede.online com seu e-mail. Assim a curadoria sabe quem pediu.</span></div><a class="btn primary block" href="#conta" data-act="acessar">Acessar a rede.online</a>`
    : `<label class="olbl" for="pnomeorg">Nome da organização</label><input id="pnomeorg" class="input" type="text" maxlength="120" autocomplete="organization">
      <label class="olbl" for="pcidorg">Cidade</label><input id="pcidorg" class="input" type="text" maxlength="80" list="capitaisorg" placeholder="Cidade, UF"><datalist id="capitaisorg">${CAPITAIS.map(c=>`<option value="${c}">`).join("")}</datalist>
      <span class="olbl" id="ptemaorg">Tema principal</span><div class="chips" role="radiogroup" aria-labelledby="ptemaorg">${TEMAS.map(t=>`<button class="chip" type="button" role="radio" data-act="pedtema" data-v="${esc(t)}" aria-checked="${S.pedTema===t}">${t}</button>`).join("")}</div>
      <label class="olbl" for="psiteorg">Site ou rede social <span class="opc">(opcional)</span></label><input id="psiteorg" class="input" type="url" maxlength="300" placeholder="https://" autocapitalize="off" spellcheck="false">
      <label class="olbl" for="pcoordorg">Quem coordena hoje</label><textarea id="pcoordorg" class="input" rows="2" maxlength="300" placeholder="Nomes e função de quem coordena"></textarea>
      <small class="ohint">Aparece na página da organização depois de aprovada. A curadoria pode pedir mais informações pelo seu e-mail.</small>
      <p id="pedmsg" class="rmsg" role="alert"></p>
      <button class="btn primary block" type="button" data-act="orgpedir" id="orgpedir">Enviar para a curadoria</button>`;
  openSheet(shead("Cadastrar uma organização") + `<div class="rform"><p class="lnote">A organização entra na rede depois que a curadoria confere que ela existe e quem a coordena. Até lá, nada aparece para outras pessoas.</p>${corpo}${pedidosLista()}</div>`, "Cadastrar uma organização");
  pedidosCarrega(); }
/* organizações aprovadas pela curadoria entram na lista de Organizações */
async function orgsAprovadasCarrega(){ if (!SB) return;
  try{ const r = await SB.from("org_pedidos").select("id,nome,cidade,tema,site,coordenacao,revisada_em").eq("status","aprovada").order("revisada_em", {ascending:false}).limit(200); if (r.error || !r.data.length) return;
    r.data.forEach(p=>{ const id = "op-" + p.id.slice(0, 8);
      p = limpoObj(p); const o = {id, nome:p.nome, sigla:siglaDe(p.nome), cidade:p.cidade, tema:p.tema, natureza:"organização verificada", real:true, cor:CORES_CONTA[parseInt(p.id.replace(/-/g,"").slice(0,6),16) % CORES_CONTA.length], membros:0,
        sobre:"Organização verificada pela curadoria da rede." + (p.coordenacao ? " Coordenação: " + p.coordenacao + "." : ""), site:p.site || ""};
      if (ORG[id]) Object.assign(ORG[id], o); else { ORG[id] = o; ORGS.push(o); } });
    if (route()==="organizacoes") render(); }catch(e){} }

