const rdUF = () => { const r = String(S.regiao || ""); const m = r.match(/,\s*([A-Z]{2})\b/) || r.match(/^([A-Z]{2})$/); if (m && UF_NOME[m[1]]) return m[1];
  const n = semAcento(r).toLowerCase(), e = Object.entries(UF_NOME).find(([sg, nm])=>n && n.includes(semAcento(nm).toLowerCase())); return e ? e[0] : ""; };
