CMNS.forEach(cmnRegistra);
/* cartão de comunidade (11 nov 2026): capa desenhada, marca sobre a capa, nome, lugar ou tema, uma linha sobre ela e a situação de quem olha */
const CMN_VER = 4;
const orgAlt = h => ["a1","a2","a3"][h % 3];   /* altura da capa na grade irregular */
const cmnHash = t => [...String(t)].reduce((a,c)=>(a*31 + c.charCodeAt(0)) % 9973, 7);
