  secvis: b => { const x = S.secoes.find(y=>y.id===b.dataset.s); if (!x) return; x.aberta = !x.aberta; persist("secoes"); profShow();
    toast(x.aberta ? `“${x.nome}” aparece no seu perfil.` : `“${x.nome}” fechada: só você vê.`); },
  secnova: () => { if (S.secoes.length >= MAX_SEC) return toast(`O perfil tem até ${MAX_SEC} seções.`); sheetSecao(null); },
  secedita: b => sheetSecao(S.secoes.find(y=>y.id===b.dataset.s)),
  secsalva: b => { const nome = (($("#secnome") || {}).value || "").trim(), m = $("#secmsg"), diz = t => { if (m) m.textContent = t; };
    const aberta = ($("#secaberta") || {getAttribute:()=>"false"}).getAttribute("aria-checked")==="true", ks = $$(".secpastas input:checked").map(i=>i.value);
    if (nome.length < 2) return diz("Dê um nome à seção.");
    if (S.secoes.some(y=>y.id!==b.dataset.s && y.nome.toLowerCase()===nome.toLowerCase())) return diz("Já existe uma seção com esse nome.");
    if (ks.length > MAX_PSEC) return diz(`Cada seção tem até ${MAX_PSEC} pastas.`);
    let x = S.secoes.find(y=>y.id===b.dataset.s);
    if (!x){ if (S.secoes.length >= MAX_SEC) return diz(`O perfil tem até ${MAX_SEC} seções.`); x = {id:"s" + Date.now().toString(36), nome, aberta, pastas:[]}; S.secoes.push(x); }
    S.secoes.forEach(y=>{ if (y!==x) y.pastas = y.pastas.filter(k=>!ks.includes(k)); });
    Object.assign(x, {nome, aberta, pastas:ks}); persist("secoes"); closeSheet();
    toast(`Seção “${nome}” ${b.dataset.s ? "salva" : "criada"}${aberta ? "" : ", fechada"}.`);
    if (route()==="perfil"){ S.profTab = "salvos"; S.profFolder = null; S.profFiltro = "tudo"; profShow(); } },
  secapaga: b => { const x = S.secoes.find(y=>y.id===b.dataset.s); if (!x) return; S.secoes = S.secoes.filter(y=>y!==x); persist("secoes"); closeSheet();
    toast(`Seção “${x.nome}” desfeita. As pastas ficaram fora das seções.`); if (route()==="perfil") profShow(); },
  pastacria: b => { const nome = (($("#pastanome") || {}).value || "").trim(), m = $("#pastamsg");
    if (nome.length < 2){ if (m) m.textContent = "Dê um nome à pasta."; return; }
    if (FOLDERS.some(f=>f[1].toLowerCase()===nome.toLowerCase())){ if (m) m.textContent = "Já existe uma pasta com esse nome."; return; }
    const sec = ($('[data-act="pastasec"]') || {}).getAttribute && $('[data-act="pastasec"]').getAttribute("aria-checked")==="true";
    const k = "p" + Date.now().toString(36); FOLDERS.push([k, nome, [], sec]);
    store.set("pastas", FOLDERS.filter(f=>/^p[a-z0-9]{5,}$/.test(f[0])).map(f=>[f[0], f[1], [], f[3]])); contaDadosAgenda("pastas");
    { const sx = S.secoes.find(x=>x.id===(($("#pastasecao") || {}).value || "")); if (sx && sx.pastas.length < MAX_PSEC){ sx.pastas.push(k); persist("secoes"); } }
    const uid = b.dataset.uid;
    if (uid){ S.saved.add(uid); S.savedIn[uid] = k; persist("saved"); persist("savedIn"); closeSheet(); refresh(uid); toast(`Pasta “${nome}” criada, com este conteúdo.`); return; }
    closeSheet(); toast(`Pasta “${nome}” criada${sec ? ", secreta" : ""}.`); if (route()==="perfil"){ S.profTab = "salvos"; S.profFolder = null; profShow(); } },
  acessar: (b, e) => { if (e) e.preventDefault(); S.contaTab = "entrar"; ME.pend = null; S.contaAbriu = Date.now(); go("conta"); },
