  redeconectar: b => sheetRedeConectar(b.dataset.r, b.dataset.t),
  rederede: b => { const v = ($("#redeuser") || {}).value || ""; sheetRedeConectar(b.dataset.r, "acompanha"); const i = $("#redeuser"); if (i) i.value = v; },
  redeopt: b => { S.redeDraft.destino = b.dataset.v; $$('[data-act="redeopt"]').forEach(x=>x.setAttribute("aria-checked", x.dataset.v===b.dataset.v)); const m = $("#redemsg"); if (m) m.textContent = ""; },
  redeembreve: b => sheetRedeEmBreve(b.dataset.r),
  redeajustar: b => sheetRedeAjustar(b.dataset.id),
  redeenviar: async () => { const D = S.redeDraft, inp = $("#redeuser"), msg = $("#redemsg"), bt = $("#redeenviar"); if (!D || !inp || !bt) return;
    const u = inp.value.trim(), diz = t => { if (msg) msg.textContent = t; }, rotulo = D.tipo==="minha" ? "Conectar" : "Acompanhar", volta = t => { bt.disabled = false; bt.textContent = rotulo; diz(t); };
    if (!u){ diz(REDES[D.rede].tel ? "Escreva o número com DDD." : "Escreva o usuário ou o endereço."); inp.focus(); return; }
    if (REDES[D.rede].soLink){ const R = REDES[D.rede], v = redeLimpa(D.rede, u);
      if (!v) return diz(R.tel ? "Confira o número: DDD e número, só algarismos. De fora do Brasil, comece com o código do país." : "Não reconhecemos esse " + (D.rede==="instagram" ? "@" : "usuário") + ". Confira e tente de novo.");
      if (S.redes.some(c=>c.rede===D.rede && c.tipo==="minha")) return diz("Você já tem um " + R.nome + " no perfil. Tire o atual para trocar.");
      const c = {id:"cx" + Date.now().toString(36), rede:D.rede, usuario:v, nome:"", perfil:redeEndereco(D.rede, v), tipo:"minha", destino:"link"};
      S.redes.push(c); persist("redes"); redeServidor("insert", c); S.redeDraft = null; render(); sheetRedes(); toast(`${R.nome} no seu perfil, como link.`); return; }
    if (D.tipo==="minha" && !D.destino){ diz("Escolha o que aparece no seu perfil."); return; }
    if (bt.disabled) return; bt.disabled = true; bt.textContent = "Buscando…"; diz("");
    let d = await redeBusca(D.rede, u);
    if (d.erro==="offline") d = redeExemplos(D.rede, u.replace(/^@/,"").replace(/^https?:\/\//,"").replace(/\/+$/,""));
    const soLink = D.tipo==="minha" && D.destino==="link", limpo = u.replace(/^@/,"").replace(/^https?:\/\//,"").replace(/\/+$/,"");
    /* só o link: a conta entra mesmo sem nada público para ler. Com prévia, o perfil de lá precisa ser público. */
    if (d.erro && soLink) d = {usuario:limpo, nome:"", perfil:redeEndereco(D.rede, u), itens:[]};
    if (d.erro) return volta(D.tipo==="minha" ? d.msg + " A prévia só funciona com o perfil público lá; você também pode conectar só o link." : d.msg);
    if (S.redes.some(c=>c.rede===D.rede && c.tipo===D.tipo && c.usuario.toLowerCase()===String(d.usuario).toLowerCase())) return volta(D.tipo==="minha" ? "Esse perfil já está conectado." : "Você já acompanha esse perfil.");
    if (!d.itens.length && !d.exemplo && !soLink) return volta(D.tipo==="minha" ? "Achamos o perfil, mas não há nada público para mostrar na prévia. Deixe o perfil público lá ou conecte só o link." : "Achamos o perfil, mas ele ainda não tem nada público para trazer.");
    const c = {id:"cx" + Date.now().toString(36), rede:D.rede, usuario:String(d.usuario), nome:d.nome || "", perfil:d.perfil || "", tipo:D.tipo, destino:D.tipo==="minha" ? D.destino : "feed"};
    S.redes.push(c); REDE_CACHE[c.id] = {em:Date.now(), itens:d.itens, exemplo:!!d.exemplo}; persist("redes"); store.set("redesCache", REDE_CACHE);
    redeServidor("insert", c); redesAplica(); S.redeDraft = null; render(); sheetRedes();
    const n = d.itens.length, R = REDES[c.rede];
    toast(d.exemplo ? `Sem conexão agora: o ${R.nome} entrou com exemplos. Os reais chegam quando a internet voltar.` : c.tipo==="minha" ? (c.destino==="link" ? `${R.nome} conectado: o link aparece no seu perfil.` : `${R.nome} conectado: ${n} ${n===1?"publicação":"publicações"}, ${destinoTxt(c)}.`) : `Você passou a acompanhar ${c.nome || c.usuario} no feed.`); },
  redesdest: async b => { const c = S.redes.find(x=>x.id===b.dataset.id); if (!c) return; const antes = c.destino; c.destino = b.dataset.v;
    $$('[data-act="redesdest"]').forEach(x=>x.setAttribute("aria-checked", x.dataset.v===c.destino));
    if (antes==="link" && c.destino!=="link"){ const m = $("#redemsg"); if (m) m.textContent = "Lendo o seu perfil público…";
      const r = await redeAtualiza(c, true), n = REDE_CACHE[c.id] ? REDE_CACHE[c.id].itens.length : 0;
      if (r!==true || !n){ c.destino = "link"; persist("redes"); sheetRedeAjustar(c.id); const m2 = $("#redemsg"); if (m2) m2.textContent = "Não há nada público para mostrar na prévia. Deixe o seu perfil público lá e tente de novo. Por enquanto fica só o link."; return; }
      store.set("redesCache", REDE_CACHE); }
    persist("redes"); redeServidor("update", c); redesAplica(); render(); sheetRedeAjustar(c.id); toast(`${REDES[c.rede].nome}: ${destinoTxt(c)}.`); },
  redeatualizar: async b => { const c = S.redes.find(x=>x.id===b.dataset.id); if (!c) return; b.disabled = true; b.textContent = "Lendo…";
    const r = await redeAtualiza(c, true); store.set("redesCache", REDE_CACHE); persist("redes"); redesAplica(); render(); sheetRedeAjustar(c.id);
    if (r!==true){ const m = $("#redemsg"); if (m) m.textContent = r.erro==="offline" ? "Sem conexão agora. Fica o que já tinha sido lido." : r.msg; } else toast("Atualizado."); },
  redesair: b => { const i = S.redes.findIndex(x=>x.id===b.dataset.id); if (i < 0) return; const c = S.redes.splice(i, 1)[0]; delete REDE_CACHE[c.id];
    persist("redes"); store.set("redesCache", REDE_CACHE); redeServidor("delete", c); redesAplica(); render(); sheetRedes();
    toast(REDES[c.rede].soLink ? `${REDES[c.rede].nome} saiu do seu perfil.` : c.tipo==="minha" ? `${REDES[c.rede].nome} desconectado. O que veio de lá saiu do seu perfil.` : `Você deixou de acompanhar ${c.nome || c.usuario}.`); },
  perto: () => { S.perto = !S.perto; persist("perto"); const o = $("#origordem"); if (o) o.outerHTML = origensOrdem(); F.key = null; render(); toast(S.perto ? "Notícias mais perto de você sobem no feed." : "A proximidade deixou de mudar a ordem do feed."); },
  origem: b => { const k = b.dataset.k, on = S.origens.includes(k);
    if (on && S.origens.length===1){ toast("Deixe ao menos uma origem ligada."); return; }
    S.origens = on ? S.origens.filter(x=>x!==k) : ORIGENS.map(o=>o[0]).filter(x=>x===k || S.origens.includes(x));
    persist("origens"); const l = $("#origlist"); if (l) l.outerHTML = origensLista();
    noticiasCarrega(); toast("Notícias de origem em " + origensNomes().toLowerCase() + "."); },
  carr: b => { const c = $("#hubcarr"), it = c && c.querySelector(".carit"); if (c) c.scrollBy({left:(+b.dataset.d) * ((it ? it.offsetWidth : 280) + 10), behavior:"smooth"}); },
  hubvotodas: () => { S.hubVoTodas = true; const y = scrollY; render(); scrollTo(0, y); },
  mobilizar: b => { S.mobRef = isNaN(+b.dataset.id) ? b.dataset.id : +b.dataset.id; sheetCreateForm(b.dataset.k); },
  tema: b => { S.tema = b.dataset.v; persist("tema"); applyTheme(); $$('[data-act="tema"]').forEach(x=>x.setAttribute("aria-checked", x.dataset.v===S.tema)); },
  pubmuda: b => { const v = b.dataset.v === "1"; if (S.publico !== v){ S.publico = v; persist("publico"); render(); toast(v ? "Seu perfil agora é público." : "Seu perfil agora é privado."); } closeSheet(); },
  ptab: b => { S.profTab = b.dataset.tab; S.profFolder = null; profShow(); },
  pfiltro: b => { S.profFiltro = b.dataset.f; S.profFolder = null; profShow(); },
