const START = "";
/* 16/11 (Amanda): abrir o endereço sem # leva sempre ao Início. Só o painel de controle do arquivo local reabre onde estava. */
/* ENDEREÇOS DIRETOS (16/11): arede.online/<nome> é uma página mínima no GitHub Pages que leva a #<nome>; aqui cada nome vira a tela certa,
   e o endereço volta para a rota de verdade sem recarregar. Rotas que já são endereços (#em-alta, #manifesto, #termos, #privacidade) não precisam de atalho. */
const ATALHOS = {tudo:{tab:"tudo"}, publicacoes:{tab:"publicacoes"}, canais:{tab:"videos"}, documentos:{tab:"documentos"},
  buscar:{r:"explorar"}, "como-funciona":{r:"funciona"}, anuncie:{r:"anunciar"}, comunidades:{r:"paginas/comunidades"}, orgs:{r:"paginas/comunidades"},
  consultas:{r:"paginas/consultas"}, eventos:{r:"paginas/eventos"}, apoie:{acao:"apoie"}};
function abaPorEndereco(){ const a = ATALHOS[location.hash.slice(1)]; if (!a) return;
  if (a.tab){ S.tab = a.tab; S.rapido = null; persist("tab"); }
  if (a.org){ S.orgAba = a.org; S.decTipo = "todos"; store.set("orgAba", a.org); }
  try{ history.replaceState(null, "", "#" + (a.r || "inicio")); }catch(err){ location.hash = a.r || "inicio"; }
  if (a.acao === "apoie") setTimeout(()=>{ try{ sheetApoie(); }catch(e){} }, 800); }
abaPorEndereco(); window.addEventListener("hashchange", abaPorEndereco);
if (!location.hash){ const ul = store.get("ultima", ""), ini = START; if (ini && ini!=="inicio"){ try{ history.replaceState(null, "", "#" + ini); }catch(err){ location.hash = ini; } } }
window.addEventListener("hashchange", render);
/* TOQUE DE NOVO NO ÍCONE DA BARRA (11 nov 2026): já estando numa seção, tocar outra vez no mesmo ícone volta ao começo dela,
   atualizado e no topo (como no Instagram e no X). Início: aba Tudo com as notícias recarregadas; Busca: sem busca nem tema;
   Comunidades: a página principal; Perfil: a aba Publicações. O Criar não entra. */
const secaoDe = r => r==="inicio" || r.startsWith("pin-") ? "inicio" : r==="explorar" ? "explorar"
  : r==="organizacoes" || r.startsWith("org-") || r==="comunidades-todas" || r==="paginas-todas" || r==="participar" ? "organizacoes"
  : r==="perfil" || r==="config" || r==="conta" || r==="perfil-ver" ? "perfil" : "";
document.addEventListener("click", e=>{ const a = e.target.closest && e.target.closest(".navbtn[data-nav]"); if (!a || e.metaKey || e.ctrlKey || e.shiftKey) return;
  const sec = a.dataset.nav; if (secaoDe(route()) !== sec) return;   /* outra seção: segue o link normal */
  e.preventDefault(); closeSheet();
  if (sec==="inicio"){ S.tab = "tudo"; persist("tab"); }
  else if (sec==="explorar"){ S.exploreQ = ""; S.exploreTema = null; }
  else if (sec==="perfil"){ S.profTab = "publicacoes"; S.profFolder = null; S.profQ = ""; }
  F.key = null;
  if (route() !== sec) location.hash = sec; else render();
  requestAnimationFrame(()=>window.scrollTo({top:0, behavior:"smooth"}));
  if (sec==="inicio") noticiasCarrega(); uso("nav", "de-novo", sec); });
if (S.localAuto && navigator.permissions && navigator.permissions.query) navigator.permissions.query({name:"geolocation"}).then(q=>{ if (q.state==="granted" && Date.now() - (S.localQuando || 0) > 6 * 3600e3) localAtualiza(true); }).catch(()=>{});
