if (/[?&]teste=1/.test(location.search)) window.__arede = {feedDadosNovos, POOL, F, sheetSugFonte, adReal, AD_REAIS_set:l=>{ AD_REAIS = l; F.key = null; render(); }, donoDe, findItem, S, ME, navConta, LV, aoVivoPinta, adPrecosAplica, USO, uso, usoEnvia, csatTenta, prox, footCtx, footInfo, PRIO, prioDe, historicoPreenche, alvoDe, PENT, COMS, pentHTML, comsHTML, PREV, cidadeNoAparelho, munCarrega, lugarSinal, lugaresInteresse, lugarInteresse, localAtualiza, nivel, ACESSO, acessoVideo, acessoPub, ledger, FEED:F, itemDaPublicacao, POOL, source, ORG, SEAL, F, passa:(it)=>passa(it,S.filt), S, ME, render, go, F, altaTeste: d => { ALTA = d; altaDesenha(); }, noticiasTeste: d => noticiasAplica(d, Date.now())};
window.addEventListener("scroll", ()=>{ const t = $("#top"); if (t) t.classList.toggle("scrolled", window.scrollY > 4); }, {passive:true});
window.addEventListener("resize", debounce(()=>{
  placeLogoDots();
  if (route()==="inicio" && F.grid && !(F.grid instanceof TileGrid)){ const n = feedCols(feedLayout()); if (n !== F.grid.n){ F.grid.n = n; F.grid.render(); } }
  if (route()==="organizacoes") ["hubch","hubvo"].forEach(k=>{ const g = GRIDS[k]; if (!g || !g.box || !g.box.isConnected) return; const n = k==="hubch" ? hubChCols(g.items.length) : feedCols(g.v); if (n !== g.n){ g.n = n; g.render(); } });
  layoutAllPins(); fitTiles(); }, 150));
/* mede as duas posições do ponto do logo (mudam com a fonte e o tamanho da tela) */
function placeLogoDots(){ $$(".logo .lw").forEach(w=>{ const a = w.querySelector(".lga"), b = w.querySelector(".lgb"), d = w.querySelector(".lmove"); if (!a || !b || !d) return;
  const lg = w.closest(".logo"); if (lg && lg.matches(":hover, :focus-visible, .abre")) return;   /* mede só em repouso */
  w.style.setProperty("--ax", a.offsetLeft + "px"); w.style.setProperty("--ay", a.offsetTop + "px");
  /* no destino, o espaço do ponto entre "a" e "rede" se fecha: desconta essa largura (medida com a marca em repouso) */
  const cs = getComputedStyle(a), fecha = a.getBoundingClientRect().width + parseFloat(cs.marginLeft) + parseFloat(cs.marginRight);
  w.style.setProperty("--bx", (b.offsetLeft - fecha) + "px"); w.style.setProperty("--by", b.offsetTop + "px"); });
  if (typeof logoHerda==="function") logoHerda(); }
/* MARCA NO TOQUE (10 nov 2026): sem mouse, o movimento do ponto acontece sozinho. A marca se completa ("arede.online") por uns
   2,5 segundos e volta ao repouso ("a.rede"): ao abrir o site, ao tocar na marca e ao voltar ao topo da página. */
const LOGO_TOQUE = matchMedia("not all and (hover:hover) and (pointer:fine)"), LOGO_CALMA = matchMedia("(prefers-reduced-motion: reduce)");
let logoAte = 0, logoT = 0, logoDesceu = false;
function logoAbre(ms=2500){ if (!LOGO_TOQUE.matches) return;
  if (LOGO_CALMA.matches){ logoAte = Infinity; $$(".logo").forEach(l=>l.classList.add("abre")); return; }   /* menos movimento: completa e parada */
  placeLogoDots(); logoAte = Date.now() + ms;
  requestAnimationFrame(()=>requestAnimationFrame(()=>{ $$(".logo").forEach(l=>l.classList.add("abre")); }));
  clearTimeout(logoT); logoT = setTimeout(()=>{ logoAte = 0; $$(".logo.abre").forEach(l=>l.classList.remove("abre")); }, ms); }
/* a tela é redesenhada a cada navegação: a marca nova herda o estado da anterior, sem pular */
const logoHerda = () => { if (LOGO_TOQUE.matches && Date.now() < logoAte) $$(".logo:not(.abre)").forEach(l=>l.classList.add("abre")); };
document.addEventListener("pointerdown", e=>{ if (e.pointerType!=="mouse" && e.target.closest && e.target.closest(".logo")) logoAbre(); }, {passive:true});
addEventListener("scroll", ()=>{ if (scrollY > 400) logoDesceu = true; else if (scrollY < 8 && logoDesceu){ logoDesceu = false; logoAbre(); } }, {passive:true});
/* ao abrir o site, o movimento só começa quando o carregamento acalma (fontes prontas, notícias desenhadas e o aparelho livre):
   no celular, ele travava quando as notícias chegavam no meio do movimento */
let LOGO_INICIO = false;
function logoInicio(){ if (LOGO_INICIO) return; LOGO_INICIO = true; placeLogoDots();
  const vai = () => window.requestIdleCallback ? requestIdleCallback(()=>requestAnimationFrame(()=>logoAbre()), {timeout:1200}) : setTimeout(logoAbre, 250);
  setTimeout(vai, 300); }
if (document.fonts && document.fonts.ready) document.fonts.ready.then(()=>{ layoutAllPins(); fitTiles(); placeLogoDots(); });
setTimeout(logoInicio, 4000);   /* se o servidor demorar, começa assim mesmo */

/* PARTICIPAÇÃO AO VIVO (Estrutura #3): a cada poucos segundos entra um voto, apoio, presença ou voluntário
   num conteúdo visível. No produto real, isso vem do servidor em tempo real; aqui é simulado. */
const LIVE_T = ["enquete","votacao","chamado","evento"];
setInterval(()=>{ if (document.hidden || $("#layer .scrim")) return;
  const els = $$('#main [data-tile], #main article[data-card]').filter(e=>{ const r = e.getBoundingClientRect(); return r.bottom > 0 && r.top < innerHeight; });
  const uids = [...new Set(els.map(e=>e.dataset.tile || e.dataset.card))];
  const its = uids.map(u=>findItem(u)).filter(it=>it && LIVE_T.includes(it.tipo) && !it.ext && !String(it.uid).startsWith("c"));
  if (!its.length) return;
  const it = its[Math.floor(Math.random()*its.length)], L = LIVE[it.id] = LIVE[it.id] || {n:0, v:[]};
  if (it.tipo==="enquete"){ const i = Math.floor(Math.random()*it.opcoes.length); L.v[i] = (L.v[i]||0) + 1; } else L.n++;
  uids.filter(u=>{ const x = findItem(u); return x && x.id===it.id; }).forEach(u=>refresh(u, true));
}, 3500);
if (PREVIA){ addEventListener("message", e => { if (!PREVIA_ORIGEM.test(e.origin)) return; const d = e.data; if (!d || d.tipo !== "arede-previa") return;
    aplicaTextos(d.textos); if (/^(manifesto|funciona)$/.test(d.rota || "")) MANIF_ON = true; manifAplica(); closeSheet();
    if (d.rota && route() !== d.rota) location.hash = d.rota; else render();
    if (d.abrir === "marca") setTimeout(()=>A.sobre(), 80);
    else if (d.alvo) setTimeout(()=>{ const el = document.getElementById(d.alvo); el && el.scrollIntoView({block:"start"}); }, 120); });
  parent.postMessage({tipo:"arede-previa-pronta"}, "*"); }
const VERSAO = "v1 registrada · 16/11 13:40";
console.info("arede.online · versão " + VERSAO);
